// FE Civil practice deck (v25). Original exam-style items mapped to the NCEES FE Civil outline. Data only.
LSA.deck({
  id: "fecivil", name: "FE Civil", icon: "📐",
  section: 'Engineer Fundamentals', format: 'practice',
  notice: "These are original practice questions written to official public outlines. They are not real past exam items, not an official NCEES or AAMI practice exam, and not a license to practice. Formulas were checked against standard public references. Consult the current FE Reference Handbook and applicable standards for official work.",
  sources: {
    "nspe-ethics": ["NSPE Code of Ethics for Engineers", "https://www.nspe.org/resources/ethics/code-ethics"],
    "openstax-calc": ["OpenStax Calculus Volume 1", "https://openstax.org/books/calculus-volume-1/pages/1-introduction"],
    "openstax-stat": ["OpenStax Introductory Statistics", "https://openstax.org/books/introductory-statistics/pages/1-introduction"],
    "openstax-up1": ["OpenStax University Physics Volume 1", "https://openstax.org/books/university-physics-volume-1/pages/1-introduction"],
    "openstax-finance": ["OpenStax Principles of Finance", "https://openstax.org/books/principles-finance/pages/1-introduction"],
    "libretexts-statics": ["LibreTexts: Engineering Statics (open textbook)", "https://eng.libretexts.org/Bookshelves/Mechanical_Engineering/Engineering_Statics_-_Open_and_Interactive_(Steinhurst_et_al)"],
    "libretexts-mom": ["LibreTexts: Introduction to Mechanics of Materials", "https://eng.libretexts.org/Bookshelves/Mechanical_Engineering/Introduction_to_Mechanics_of_Materials_(Penenik)"],
    "usgs-water": ["USGS Water Science School", "https://www.usgs.gov/special-topics/water-science-school"],
    "fhwa-hds5": ["FHWA Hydraulic Design of Highway Culverts (HDS-5)", "https://www.fhwa.dot.gov/engineering/hydraulics/pubs/08090/"],
    "fhwa-hec22": ["FHWA Urban Drainage Design Manual (HEC-22)", "https://www.fhwa.dot.gov/engineering/hydraulics/library/listing.cfm"],
    "fhwa-geom": ["FHWA Office of Safety, geometric design and sight distance", "https://highways.dot.gov/safety"],
    "fhwa-mutcd": ["FHWA: Manual on Uniform Traffic Control Devices", "https://mutcd.fhwa.dot.gov/"],
    "fhwa-contracts": ["FHWA Construction Program Guide: Contract Administration", "https://www.fhwa.dot.gov/construction/cqit/"],
    "fhwa-pavement": ["FHWA Pavement and Materials", "https://www.fhwa.dot.gov/pavement/"],
    "epa-waste": ["EPA National Pollutant Discharge Elimination System", "https://www.epa.gov/npdes"],
    "osha-const": ["OSHA Construction Industry", "https://www.osha.gov/construction"],
    "nrcs-ssm": ["USDA NRCS Soil Survey Manual", "https://www.nrcs.usda.gov/resources/guides-and-instructions/soil-survey-manual"],
    "usace-settle": ["USACE EM 1110-1-1904, Settlement Analysis", "https://www.publications.usace.army.mil/portals/76/publications/engineermanuals/em_1110-1-1904.pdf"],
    "usace-slope": ["USACE EM 1110-2-1902, Slope Stability", "https://www.publications.usace.army.mil/portals/76/publications/engineermanuals/em_1110-2-1902.pdf"],
    "awc-nds": ["American Wood Council, National Design Specification (NDS)", "https://awc.org/codes-standards/publications/nds-2024"],
    "ngs": ["NOAA National Geodetic Survey", "https://geodesy.noaa.gov/"],
    "ncees-ref": ["NCEES FE Reference Handbook (formula check; text not copied here)", "https://ncees.org/exams/exam-preparation-materials/"],
    "ncees-spec": ["NCEES FE Civil CBT Exam Specifications (effective July 2020)", "https://ncees.org/wp-content/uploads/FE-Civil-CBT-specs-1.pdf"],
    "epa-wastewater": ["EPA: Municipal Wastewater", "https://www.epa.gov/npdes/municipal-wastewater"],
    "epa-drinking": ["EPA: Ground Water and Drinking Water", "https://www.epa.gov/ground-water-and-drinking-water"],
    "fhwa-schedule": ["FHWA Guide for Construction Contract Time Determination Procedures", "https://www.fhwa.dot.gov/construction/contracts/t508015.cfm"],
  },
  cards: [
    { id: "fe001", ages: 'both', topic: "math", s: "What is the derivative of \\(3x^{2}+2x\\) evaluated at \\(x=4\\)?", c: ["28", "26", "48", "52"], f: "Differentiate term by term: \\(\\frac{d}{dx}(3x^{2}+2x)=6x+2\\). At \\(x=4\\), \\(6(4)+2=26\\).", src: "openstax-calc", also: ["ncees-ref"] },
    { id: "fe002", ages: 'both', topic: "math", s: "Evaluate \\(\\int_{0}^{3} 2x\\,dx\\).", c: ["6", "9", "8", "3"], f: "The antiderivative is \\(x^{2}\\). Evaluating the definite integral gives 9.", src: "openstax-calc", also: ["ncees-ref"] },
    { id: "fe003", ages: 'both', topic: "math", s: "What is the magnitude of the vector \\(\\langle 3,4\\rangle\\)?", c: ["7", "5", "12", "25"], f: "Magnitude is \\(\\sqrt{3^{2}+4^{2}}=5\\), the length of that vector.", src: "openstax-calc", also: ["ncees-ref"] },
    { id: "fe004", ages: 'both', topic: "math", s: "Compute the dot product \\(\\langle 2,3\\rangle\\cdot\\langle 4,-1\\rangle\\).", c: ["8", "5", "-3", "11"], f: "The dot product adds the pairwise products, and the result is 5.", src: "openstax-calc", also: ["ncees-ref"] },
    { id: "fe005", ages: 'both', topic: "math", s: "What is the arithmetic mean of the data set 2, 4, 6, 8, and 10?", c: ["5", "6", "4", "3"], f: "The mean is the sum of those values divided by how many there are, which is 6.", src: "openstax-stat", also: ["ncees-ref"] },
    { id: "fe006", ages: 'both', topic: "math", s: "For the sample 2, 4, 6, what is the sample standard deviation? Use \\(s=\\sqrt{\\sum(x-\\bar{x})^{2}/(n-1)}\\).", c: ["1.63", "2", "4", "3"], f: "The sample standard deviation of these values is 2.", src: "openstax-stat", also: ["ncees-ref"] },
    { id: "fe007", ages: 'both', topic: "math", s: "If \\(\\Phi(1.00)=0.8413\\) for the standard normal distribution, what is \\(P(Z>1.00)\\)?", c: ["0.8413", "0.1587", "0.5000", "0.3174"], f: "The upper tail beyond \\(z=1.00\\) is \\(0.1587\\).", src: "openstax-stat", also: ["ncees-ref"] },
    { id: "fe008", ages: 'both', topic: "math", s: "A random sample of \\(n=25\\) has mean 10. The population standard deviation is 2. Using \\(z=1.96\\), what is the half-width of a 95% confidence interval for the mean?", c: ["0.080", "0.784", "1.960", "0.392"], f: "Using the usual 95% z value, the confidence half-width is \\(z\\sigma/\\sqrt{n}=0.784\\).", src: "openstax-stat", also: ["ncees-ref"] },
    { id: "fe009", ages: 'both', topic: "math", s: "What is the distance from \\((0,0)\\) to \\((5,12)\\)?", c: ["17", "13", "60", "26"], f: "Distance is \\(\\sqrt{5^{2}+12^{2}}=\\sqrt{25+144}=\\sqrt{169}=13\\).", src: "openstax-calc", also: ["ncees-ref"] },
    { id: "fe010", ages: 'both', topic: "math", s: "A right triangle has legs 6 m and 8 m. What is its area?", c: ["\\(48\\,\\mathrm{m}^{2}\\)", "\\(24\\,\\mathrm{m}^{2}\\)", "\\(14\\,\\mathrm{m}^{2}\\)", "\\(10\\,\\mathrm{m}^{2}\\)"], f: "Area of a right triangle is \\(\\frac{1}{2}ab=\\frac{1}{2}(6)(8)=24\\,\\mathrm{m}^{2}\\). The 6-8-10 triple gives the hypotenuse of 10 m, which is a length, not an area.", src: "openstax-calc", also: ["ncees-ref"] },
    { id: "fe011", ages: 'both', topic: "math", s: "What is \\(\\sin 30^{\\circ}\\)?", c: ["0.866", "0.5", "1.0", "0.707"], f: "The sine of 30 degrees is 0.5, a standard value from the unit circle.", src: "openstax-calc", also: ["ncees-ref"] },
    { id: "fe012", ages: 'both', topic: "math", s: "What is \\(\\log_{10}(1000)\\)?", c: ["2", "3", "1", "0"], f: "Because \\(10^{3}=1000\\), \\(\\log_{10}(1000)=3\\).", src: "openstax-calc", also: ["ncees-ref"] },
    { id: "fe013", ages: 'both', topic: "math", s: "How many ways can 2 items be chosen from 5 if order does not matter?", c: ["20", "10", "5", "25"], f: "The combination count for this pair from the set is 10.", src: "openstax-calc", also: ["ncees-ref"] },
    { id: "fe014", ages: 'both', topic: "math", s: "A line has slope 2 and y-intercept 1. What is y when \\(x=3\\)?", c: ["5", "7", "6", "8"], f: "The line is \\(y=2x+1\\). At \\(x=3\\), \\(y=7\\).", src: "openstax-calc", also: ["ncees-ref"] },
    { id: "fe015", ages: 'both', topic: "math", s: "The k-component of \\(\\langle 3,4,0\\rangle\\times\\langle 1,2,0\\rangle\\) is which value?", c: ["10", "2", "8", "11"], f: "The k (z) component of a 2-D cross product is \\(3(2)-4(1)=6-4=2\\).", src: "openstax-calc", also: ["ncees-ref"] },
    { id: "fe016", ages: 'both', topic: "math", s: "A linear fit is \\(y=3x+1\\). What predicted y goes with \\(x=5\\)?", c: ["15", "16", "8", "12"], f: "Substitute: \\(y=3(5)+1=16\\). Regression predictions use the fitted line at the given x.", src: "openstax-calc", also: ["ncees-ref"] },
    { id: "fe017", ages: 'both', topic: "ethics", s: "A client asks you to sign and seal a design you did not prepare and did not supervise. What does the NSPE Code of Ethics require?", c: ["Seal the work you did not prepare or supervise, if the client agrees in writing", "Do not seal the work you did not prepare or supervise", "Seal the work you did not prepare or supervise, and add a later disclaimer", "Seal the work you did not prepare or supervise, because a junior already checked"], f: "NSPE rules of practice require engineers not to seal work they did not prepare or supervise, and to sign only work under their responsible charge and supervision. Public safety depends on that personal responsibility.", src: "nspe-ethics", also: ["ncees-spec"] },
    { id: "fe018", ages: 'both', topic: "ethics", s: "You discover a safety defect in a project after construction has started. The client wants it kept quiet to avoid delay. What comes first under the NSPE Code?", c: ["Keep the client's schedule confidential after a defect is found, and withhold notification", "Hold public safety, health, and welfare paramount", "Ignore the defect if the agreement is already signed and paid", "Leave the defect in the drawings and hope the issue goes unnoticed"], f: "A known safety defect cannot be hidden to protect schedule or cost. The first fundamental canon is to hold paramount the safety, health, and welfare of the public.", src: "nspe-ethics", also: ["ncees-spec"] },
    { id: "fe019", ages: 'both', topic: "ethics", s: "A vendor offers you a costly personal gift while you are evaluating bids. What is the ethical action?", c: ["Accept the gift and still plan to award the work to the lowest bid", "Refuse the gift and stay impartial in the bid review", "Accept the gift and keep it from others in your firm", "Accept the gift after the agreement is already signed and filed"], f: "Engineers must act as faithful agents and avoid conflicts of interest. A personal gift from a bidder can bias, or appear to bias, a bid review, so refuse the gift and stay impartial.", src: "nspe-ethics", also: ["ncees-spec"] },
    { id: "fe020", ages: 'both', topic: "ethics", s: "Passing the FE exam, by itself, authorizes you to do which of the following?", c: ["Practice as a licensed professional engineer, including sealing plans", "Apply for the EIT or engineer intern status in many jurisdictions", "Seal structural or civil drawings for a public building", "Use the title Professional Engineer immediately"], f: "Passing the FE exam is a step toward licensure and, in many jurisdictions, supports EIT or engineer intern status. A PE license still requires the board's experience and PE exam requirements. Sealing work and using the PE title require a license.", src: "nspe-ethics", also: ["ncees-spec"] },
    { id: "fe021", ages: 'both', topic: "ethics", s: "When may an engineer disclose a client's confidential business information?", c: ["Whenever a new employer would find the information useful", "When required by the law, or when public safety demands it", "If a competitor or vendor asks for it in writing", "After the client's invoice has been paid in full"], f: "Engineers act as faithful agents and keep confidential information gained in professional service, except when required by law to disclose it or when public safety demands disclosure.", src: "nspe-ethics", also: ["ncees-spec"] },
    { id: "fe022", ages: 'both', topic: "ethics", s: "You are asked to make a public statement about a project. The NSPE Code requires that your statement be:", c: ["A claim written to match the owner's or sponsor's preferred outlook", "Objective, truthful, and within your competence", "Rounded up to help the contractor win the next job", "Left blank so the owner can fill it in later"], f: "Engineers must issue public statements only in an objective and truthful manner and must not speak outside their competence. Hiding known risks or stretching claims violates that duty.", src: "nspe-ethics", also: ["ncees-spec"] },
    { id: "fe023", ages: 'both', topic: "ethics", s: "Professional liability for an engineer most often arises from which standard?", c: ["A project that loses money for the owner", "Failure to use the care of a reasonably prudent engineer", "A design that costs more than other options on the market", "A result that differs from your earlier sketch"], f: "Professional negligence is judged against the standard of care: the care, skill, and diligence that a reasonably prudent engineer in the same situation would use. A bad business outcome by itself is not negligence.", src: "nspe-ethics", also: ["ncees-spec"] },
    { id: "fe024", ages: 'both', topic: "ethics", s: "A valid contract typically requires an offer, acceptance, and which additional element?", c: ["A requirement that payment be made in cash only", "A bargained-for exchange, called consideration", "A handshake photographed for the file", "The engineer's professional stamp alone"], f: "In contract law, a bargain generally needs offer, acceptance, and consideration: each side gives or promises something of legal value, a bargained-for exchange. A PE seal or cash payment is not a required element of formation.", src: "nspe-ethics", also: ["ncees-spec"] },
    { id: "fe025", ages: 'both', topic: "econ", s: "What is the future worth of $1,000 invested for 5 years at 8% per year, compounded annually?", c: ["$1,550", "$1,469", "$1,800", "$1,600"], f: "Future worth is \\(F=P(1+i)^{n}=1000(1.08)^{5}=1,469.33\\), which rounds to $1,469.", src: "openstax-finance", also: ["ncees-ref"] },
    { id: "fe026", ages: 'both', topic: "econ", s: "What is the present worth of $2,000 received in 3 years if i=6% per year, compounded annually?", c: ["$1,887", "$1,679", "$2,382", "$1,200"], f: "Present worth is \\(P=F/(1+i)^{n}=2000/(1.06)^{3}=1,679.24\\), which rounds to $1,679.", src: "openstax-finance", also: ["ncees-ref"] },
    { id: "fe027", ages: 'both', topic: "econ", s: "A loan of $10,000 is to be repaid in 4 equal annual payments at 10% per year. What is each payment?", c: ["$2,500", "$3,155", "$2,800", "$1,000"], f: "Capital recovery: \\(A=P\\left[i(1+i)^{n}/((1+i)^{n}-1)\\right]=10000[0.1(1.1)^{4}/((1.1)^{4}-1)]=3,154.70\\), about $3,155.", src: "openstax-finance", also: ["ncees-ref"] },
    { id: "fe028", ages: 'both', topic: "econ", s: "A firm already spent $50,000 on a study that cannot be recovered. In a go or no-go decision from this point, that $50,000 is:", c: ["Added to future costs or benefits in the analysis", "A sunk cost and should be ignored in the analysis", "Treated as a future annual cost", "Used as the present worth of the project"], f: "A sunk cost has already been spent and cannot be changed by the decision at hand. Economic analysis of remaining alternatives should ignore it and compare only future cash flows.", src: "openstax-finance", also: ["ncees-ref"] },
    { id: "fe029", ages: 'both', topic: "econ", s: "Fixed cost is $2,000. Variable cost is $5 per unit. Selling price is $15 per unit. What is the break-even quantity?", c: ["133 units", "200 units", "400 units", "100 units"], f: "Break-even is \\(Q=FC/(p-v)=2000/(15-5)=200\\) units. Using \\(p\\) or \\(v\\) alone in the denominator is a common error.", src: "openstax-finance", also: ["ncees-ref"] },
    { id: "fe030", ages: 'both', topic: "econ", s: "A project's present worth of benefits is $120,000 and present worth of costs is $100,000. What is the benefit-cost ratio?", c: ["0.83", "1.20", "20,000", "1.00"], f: "The benefit-cost ratio is \\(PW_{benefits}/PW_{costs}=1.20\\). A ratio above one supports the project on a PW basis.", src: "openstax-finance", also: ["ncees-ref"] },
    { id: "fe031", ages: 'both', topic: "econ", s: "A nominal interest rate of 12% per year is compounded monthly. What is the effective annual rate?", c: ["12.00%", "12.68%", "1.00%", "13.00%"], f: "Effective annual rate is 12.68%, from compounding the nominal rate over the periods in a year.", src: "openstax-finance", also: ["ncees-ref"] },
    { id: "fe032", ages: 'both', topic: "econ", s: "A decision has a 0.20 chance of a $100 gain and a 0.80 chance of a $20 loss. What is the expected value?", c: ["$80", "$4", "$16", "-$4"], f: "Expected value is \\(E[X]=4\\), the probability-weighted average of the outcomes.", src: "openstax-finance", also: ["ncees-ref"] },
    { id: "fe033", ages: 'both', topic: "econ", s: "A machine costs $10,000 now and returns $3,000 at the end of each of 4 years. If i=10%, what is the approximate net present worth?", c: ["$2,000", "-$490", "$3,000", "$1,200"], f: "Net PW is about -$490, using the uniform-series present-worth factor at the stated rate and life.", src: "openstax-finance", also: ["ncees-ref"] },
    { id: "fe034", ages: 'both', topic: "econ", s: "In present-worth analysis at a given MARR, you should choose the mutually exclusive alternative that has:", c: ["The largest initial cost", "The largest net present worth", "The shortest life, regardless of the PW", "The largest future salvage, ignoring PW"], f: "For mutually exclusive projects compared at the same MARR, select the alternative with the greatest net present worth (do-nothing has PW=0). First cost or life alone is not the decision rule.", src: "openstax-finance", also: ["ncees-ref"] },
    { id: "fe035", ages: 'both', topic: "statics", s: "A simply supported beam of span L carries a concentrated load P at midspan. What is the left support reaction?", c: ["\\(P\\)", "\\(P/2\\)", "\\(P/4\\)", "\\(P/8\\)"], f: "By symmetry, or by summing moments about the right support, \\(R_A L - P(L/2)=0\\), so \\(R_A=P/2\\). Each support carries half the load.", src: "libretexts-statics", also: ["openstax-up1", "ncees-ref"], img: "img/fe-beam-mid.svg", imgAlt: "Simply supported beam AB with span L and a downward point load P at midspan.", imgAsk: true },
    { id: "fe036", ages: 'both', topic: "statics", s: "A \\(20\\,\\mathrm{kN}\\) load acts at midspan of an 8 m simply supported beam. What is the reaction at A?", c: ["\\(20\\,\\mathrm{kN}\\)", "\\(10\\,\\mathrm{kN}\\)", "\\(25\\,\\mathrm{kN}\\)", "\\(15\\,\\mathrm{kN}\\)"], f: "Midspan load is shared equally: \\(R_A=P/2=20/2=10\\) kN. Taking the full load at A, or using P/4, are common errors.", src: "libretexts-statics", also: ["openstax-up1", "ncees-ref"], img: "img/fe-beam-mid.svg", imgAlt: "Simply supported beam AB with a point load P at midspan.", imgAsk: true },
    { id: "fe037", ages: 'both', topic: "statics", s: "A 10 m simply supported beam has a \\(30\\,\\mathrm{kN}\\) point load 4 m from A and 6 m from B. What is the reaction at A?", c: ["\\(12\\,\\mathrm{kN}\\)", "\\(18\\,\\mathrm{kN}\\)", "\\(10\\,\\mathrm{kN}\\)", "\\(15\\,\\mathrm{kN}\\)"], f: "Moments about B: \\(R_A(10)-30(6)=0\\), so \\(R_A=18\\) kN.", src: "libretexts-statics", also: ["openstax-up1", "ncees-ref"], img: "img/fe-beam-offset.svg", imgAlt: "Simply supported beam AB with point load P a distance a from A and b from B.", imgAsk: true },
    { id: "fe038", ages: 'both', topic: "statics", s: "A rigid body is in static equilibrium. Which statement is correct?", c: ["Applied forces have to share one concurrent line of action", "The resultant force and the resultant moment are both zero", "Each reaction is a roller and a cable", "The centroid of the body is at a support and a pin"], f: "Equilibrium requires \\(\\sum F=0\\) and \\(\\sum M=0\\). In equilibrium, the resultant force and the resultant moment are both zero. Either condition alone is not enough. Forces need not share one line of action if moments also cancel.", src: "libretexts-statics", also: ["openstax-up1", "ncees-ref"] },
    { id: "fe039", ages: 'both', topic: "statics", s: "Two 50 N forces act on a particle at 90 degrees. What is the magnitude of the resultant?", c: ["100 N", "70.7 N", "50 N", "25 N"], f: "For perpendicular forces, \\(R=\\sqrt{50^{2}+50^{2}}=50\\sqrt{2}=70.7\\) N.", src: "libretexts-statics", also: ["openstax-up1", "ncees-ref"] },
    { id: "fe040", ages: 'both', topic: "statics", s: "The centroid of a rectangular area of width b and height h, measured from a base edge, is at:", c: ["\\(h/3\\) from the base", "\\(h/2\\) from the base", "\\(h/4\\) from the base", "\\(2h/3\\) from the base"], f: "A rectangle is symmetric, so its centroid is at the geometric center, \\(h/2\\) from the base (or from either parallel edge).", src: "libretexts-statics", also: ["openstax-up1", "ncees-ref"] },
    { id: "fe041", ages: 'both', topic: "statics", s: "The area moment of inertia of a rectangle of width b and height h about its centroidal axis parallel to the width is:", c: ["\\(bh^{3}/3\\)", "\\(bh^{3}/12\\)", "\\(b^{3}h/12\\)", "\\(bh/12\\)"], f: "For a rectangle about the centroidal axis through the mid-height and parallel to b, \\(I=bh^{3}/12\\). About a base edge it is \\(bh^{3}/3\\) by the parallel-axis theorem.", src: "libretexts-statics", also: ["openstax-up1", "ncees-ref"] },
    { id: "fe042", ages: 'both', topic: "statics", s: "A \\(100\\,\\mathrm{mm}\\) by \\(200\\,\\mathrm{mm}\\) rectangle is considered with h=\\(200\\,\\mathrm{mm}\\) about its centroidal axis parallel to the \\(100\\,\\mathrm{mm}\\) side. What is I in \\(\\mathrm{m}^{4}\\)?", c: ["\\(2.00\\times 10^{-4}\\,\\mathrm{m}^{4}\\)", "\\(6.67\\times 10^{-5}\\,\\mathrm{m}^{4}\\)", "\\(3.33\\times 10^{-5}\\,\\mathrm{m}^{4}\\)", "\\(8.00\\times 10^{-6}\\,\\mathrm{m}^{4}\\)"], f: "Convert to meters: b=0.10 m, h=0.20 m. \\(I=bh^{3}/12=(0.10)(0.20)^{3}/12=6.67\\times 10^{-5}\\) m\\(^{4}\\).", src: "libretexts-statics", also: ["openstax-up1", "ncees-ref"] },
    { id: "fe043", ages: 'both', topic: "statics", s: "A 40 kg crate rests on a horizontal floor. The static friction coefficient is 0.30. What is the smallest horizontal force that starts motion? Use g=\\(9.81\\,\\mathrm{m}/\\mathrm{s}^{2}\\).", c: ["392 N", "118 N", "12 N", "40 N"], f: "Impending motion: \\(F=\\mu N=\\mu mg=0.30(40)(9.81)=117.7\\) N, about 118 N. Using mg without mu, or forgetting g, are common errors.", src: "libretexts-statics", also: ["openstax-up1", "ncees-ref"] },
    { id: "fe044", ages: 'both', topic: "statics", s: "Two non-collinear members meet at an unloaded truss joint, and no other member or support is there. Those members are:", c: ["Assumed to carry shear and bending like beam elements", "Zero-force members, by the usual joint rule", "Treated as cables that can carry tension only", "Rigid moment connections rather than truss members"], f: "If only two non-collinear members meet at a joint with no external load or support, both are zero-force members by the usual joint rule. If the two members are collinear, they can carry equal and opposite axial load.", src: "libretexts-statics", also: ["openstax-up1", "ncees-ref"] },
    { id: "fe045", ages: 'both', topic: "statics", s: "A 3-member truss ABC is an isosceles right layout: AB is horizontal, C is above the midpoint, and AC=BC. A downward load P acts at C. What is the vertical reaction at A?", c: ["\\(P\\)", "\\(P/2\\)", "0", "\\(P/\\sqrt{2}\\)"], f: "Supports at A and B share the vertical load equally by symmetry, so \\(R_{Av}=P/2\\). The sloped members carry axial force, but the vertical support share is still P/2.", src: "libretexts-statics", also: ["openstax-up1", "ncees-ref"], img: "img/fe-truss.svg", imgAlt: "Isosceles right truss ABC with a 90 degree angle at C, supports at A and B, and a downward load P at C.", imgAsk: true },
    { id: "fe046", ages: 'both', topic: "statics", s: "If two forces are equal, opposite, and collinear, their resultant is:", c: ["A couple", "Zero", "Twice one force", "A moment equal to the product of force and spacing"], f: "The resultant of those equal, opposite, and collinear forces is zero. Equal, opposite, and collinear forces cancel. A couple requires equal, opposite, and parallel forces that are not collinear.", src: "libretexts-statics", also: ["openstax-up1", "ncees-ref"] },
    { id: "fe047", ages: 'both', topic: "statics", s: "The moment of a 50 N force about a point 0.40 m from its line of action is:", c: ["12.5 N·m", "20 N·m", "50 N·m", "0.40 N·m"], f: "Moment is \\(M=Fd=50(0.40)=20\\) N·m when d is the perpendicular distance to the line of action.", src: "libretexts-statics", also: ["openstax-up1", "ncees-ref"] },
    { id: "fe048", ages: 'both', topic: "statics", s: "A 6 m beam carries a uniform load of \\(4\\,\\mathrm{kN}\\)/m over the full span. What is the reaction at each simple support?", c: ["\\(24\\,\\mathrm{kN}\\)", "\\(12\\,\\mathrm{kN}\\)", "\\(18\\,\\mathrm{kN}\\)", "\\(16\\,\\mathrm{kN}\\)"], f: "The uniform load is shared equally by the two supports, so each reaction is \\(12\\,\\mathrm{kN}\\).", src: "libretexts-statics", also: ["openstax-up1", "ncees-ref"], img: "img/fe-beam-udl.svg", imgAlt: "Simply supported beam AB with a uniform load w along the full span L.", imgAsk: true },
    { id: "fe049", ages: 'both', topic: "statics", s: "The centroid of a triangular area of height h, measured from the base, is at:", c: ["h/2 from the base", "h/3 from the base", "h/4 from the base", "h from the base"], f: "The centroid of a triangle lies at \\(h/3\\) from the base (measured from that base edge).", src: "libretexts-statics", also: ["openstax-up1", "ncees-ref"] },
    { id: "fe050", ages: 'both', topic: "statics", s: "A 2-D force system is equivalent to a single force at a point plus:", c: ["A second force applied at the same point", "A moment (couple) about the point", "A distributed torque that cannot be moved", "A second-moment of inertia for a particle"], f: "Any planar force system reduces to a resultant force and a resultant moment (couple) about a chosen point. If the point is on the line of the resultant, the moment may be zero.", src: "libretexts-statics", also: ["openstax-up1", "ncees-ref"] },
    { id: "fe051", ages: 'both', topic: "dynamics", s: "A particle starts from rest and accelerates at \\(3\\,\\mathrm{m}/\\mathrm{s}^{2}\\) for 4 s. What is its speed?", c: ["\\(7\\,\\mathrm{m/s}\\)", "\\(12\\,\\mathrm{m/s}\\)", "\\(0.75\\,\\mathrm{m/s}\\)", "\\(24\\,\\mathrm{m/s}\\)"], f: "For constant acceleration from rest, \\(v=at=3(4)=12\\) m/s. Distance would be \\(\\frac{1}{2}at^{2}=24\\) m, which is not the speed.", src: "openstax-up1", also: ["ncees-ref"] },
    { id: "fe052", ages: 'both', topic: "dynamics", s: "A particle starts from rest and accelerates at \\(3\\,\\mathrm{m}/\\mathrm{s}^{2}\\) for 4 s. How far does it travel?", c: ["12 m", "24 m", "16 m", "6 m"], f: "From rest, \\(s=\\frac{1}{2}at^{2}=\\frac{1}{2}(3)(16)=24\\) m. Using \\(vt=12(4)=48\\) m wrongly treats speed as constant.", src: "openstax-up1", also: ["ncees-ref"] },
    { id: "fe053", ages: 'both', topic: "dynamics", s: "A 10 kg mass is accelerated horizontally at \\(2\\,\\mathrm{m}/\\mathrm{s}^{2}\\) on a frictionless surface. What net force is required?", c: ["10 N", "20 N", "5 N", "19.6 N"], f: "Newton's second law: \\(F=ma=10(2)=20\\) N. Weight \\(mg=98\\) N is not the net horizontal force here.", src: "openstax-up1", also: ["ncees-ref"] },
    { id: "fe054", ages: 'both', topic: "dynamics", s: "A \\(4\\,\\mathrm{kg}\\) particle moves at \\(5\\,\\mathrm{m/s}\\). What is its kinetic energy?", c: ["60 J", "50 J", "80 J", "100 J"], f: "Kinetic energy is \\(KE=\\frac{1}{2}mv^{2}=\\frac{1}{2}(4)(25)=50\\) J. Using \\(mv\\) or \\(mv^{2}\\) without 1/2 are common errors.", src: "openstax-up1", also: ["ncees-ref"] },
    { id: "fe055", ages: 'both', topic: "dynamics", s: "A \\(2\\,\\mathrm{kg}\\) particle moving at \\(6\\,\\mathrm{m/s}\\) is brought to rest by a constant force in \\(0.50\\,\\mathrm{s}\\). What is the magnitude of the force?", c: ["6 N", "24 N", "12 N", "3 N"], f: "Impulse equals change in momentum: \\(F\\Delta t=m\\Delta v\\), so \\(F=m v/\\Delta t=2(6)/0.50=24\\) N.", src: "openstax-up1", also: ["ncees-ref"] },
    { id: "fe056", ages: 'both', topic: "dynamics", s: "The mass moment of inertia of a particle of mass m at a distance r from an axis is:", c: ["\\(mr\\)", "\\(mr^{2}\\)", "\\(m/r^{2}\\)", "\\(mr^{3}\\)"], f: "By definition, \\(I=mr^{2}\\) for a particle about a chosen axis. This is the building block for rigid-body mass moments of inertia.", src: "openstax-up1", also: ["ncees-ref"] },
    { id: "fe057", ages: 'both', topic: "dynamics", s: "A 3 kg block slides 2.0 m down a frictionless 30 degree incline. How much kinetic energy does it gain? Use g=\\(9.81\\,\\mathrm{m}/\\mathrm{s}^{2}\\).", c: ["58.9 J", "29.4 J", "19.6 J", "9.81 J"], f: "The loss in potential energy equals the gain in KE: \\(\\Delta KE=mgh=mg(L\\sin\\theta)=3(9.81)(2\\sin 30^{\\circ})=3(9.81)(1)=29.43\\) J.", src: "openstax-up1", also: ["ncees-ref"] },
    { id: "fe058", ages: 'both', topic: "dynamics", s: "Power, in mechanical work terms, is defined as:", c: ["Force divided by velocity", "The time rate of doing work", "Newton's second-law force, written as \\(F=ma\\)", "The product of work and time"], f: "By definition \\(P=dW/dt\\), which is the time rate of doing work, and in a special case also \\(P=Fv\\). \\(F/v\\) and \\(W t\\) are not power.", src: "openstax-up1", also: ["ncees-ref"] },
    { id: "fe059", ages: 'both', topic: "mom", s: "A \\(500\\,\\mathrm{kN}\\) axial load is applied to a bar with a \\(0.010\\,\\mathrm{m}^{2}\\) cross section. What is the axial stress?", c: ["\\(5\\,\\mathrm{MPa}\\)", "\\(50\\,\\mathrm{MPa}\\)", "\\(20\\,\\mathrm{MPa}\\)", "\\(0.05\\,\\mathrm{MPa}\\)"], f: "Axial stress is \\(\\sigma=P/A=500\\times 10^{3}/0.010=5.0\\times 10^{7}\\) Pa \\(=50\\) MPa.", src: "libretexts-mom", also: ["ncees-ref"] },
    { id: "fe060", ages: 'both', topic: "mom", s: "A steel bar (E=\\(200\\,\\mathrm{GPa}\\)) is 2.0 m long and has A=\\(400\\,\\mathrm{mm}^{2}\\). A \\(40\\,\\mathrm{kN}\\) axial tension is applied. What is the elongation?", c: ["\\(0.50\\,\\mathrm{mm}\\)", "\\(1.00\\,\\mathrm{mm}\\)", "\\(2.00\\,\\mathrm{mm}\\)", "\\(10.0\\,\\mathrm{mm}\\)"], f: "\\(\\delta=PL/AE\\). Convert: \\(A=400\\times 10^{-6}\\) m\\(^{2}\\), \\(E=200\\times 10^{9}\\) Pa. \\(\\delta=40000(2)/(400e-6 \\times 200e9)=0.001\\) m \\(=1.00\\) mm.", src: "libretexts-mom", also: ["ncees-ref"] },
    { id: "fe061", ages: 'both', topic: "mom", s: "For a circular shaft, torsional shear stress at radius c is \\(\\tau=Tc/J\\). For a solid circle, J is:", c: ["\\(\\pi d^{4}/64\\)", "\\(\\pi d^{4}/32\\)", "\\(\\pi d^{4}/4\\)", "\\(\\pi d^{4}/16\\)"], f: "The polar moment of inertia of a solid circular section is \\(J=\\pi d^{4}/32=\\pi c^{4}/2\\).", src: "libretexts-mom", also: ["ncees-ref"] },
    { id: "fe062", ages: 'both', topic: "mom", s: "A solid \\(40\\,\\mathrm{mm}\\) diameter shaft carries a torque of 800 N·m. What is the maximum shear stress?", c: ["\\(31.8\\,\\mathrm{MPa}\\)", "\\(63.7\\,\\mathrm{MPa}\\)", "\\(15.9\\,\\mathrm{MPa}\\)", "\\(127\\,\\mathrm{MPa}\\)"], f: "\\(J=\\pi d^{4}/32=\\pi(0.040)^{4}/32=2.513\\times 10^{-7}\\) m\\(^{4}\\). Then \\(\\tau=Tc/J=800(0.020)/J=6.37\\times 10^{7}\\) Pa \\(=63.7\\) MPa.", src: "libretexts-mom", also: ["ncees-ref"] },
    { id: "fe063", ages: 'both', topic: "mom", s: "A simply supported beam of span L carries a midspan point load P. The maximum moment is:", c: ["\\(PL/2\\)", "\\(PL/4\\)", "\\(PL/8\\)", "\\(PL\\)"], f: "Each reaction is half the load. The moment at midspan is \\(PL/4\\).", src: "libretexts-mom", also: ["ncees-ref"], img: "img/fe-beam-mid.svg", imgAlt: "Simply supported beam with a concentrated load P at midspan.", imgAsk: true },
    { id: "fe064", ages: 'both', topic: "mom", s: "A simply supported beam of span L carries a uniform load w (force per length) over the full span. The maximum moment is:", c: ["\\(wL^{2}/4\\)", "\\(wL^{2}/8\\)", "\\(wL^{2}/2\\)", "\\(wL/8\\)"], f: "For a simple beam with a uniform load, the midspan moment is \\(wL^{2}/8\\).", src: "libretexts-mom", also: ["ncees-ref"], img: "img/fe-beam-udl.svg", imgAlt: "Simply supported beam with a uniform load w over span L.", imgAsk: true },
    { id: "fe065", ages: 'both', topic: "mom", s: "Bending stress in a beam is \\(\\sigma=My/I\\). At a given section, the maximum bending stress occurs at:", c: ["The neutral axis of the section", "The farthest fiber from the neutral axis", "The mid-depth of the flange", "The plastic neutral axis of a steel beam"], f: "Because \\(\\sigma\\) is proportional to y, the farthest fiber from the neutral axis (the extreme fiber, largest |y|) has the largest bending stress. The neutral axis has y=0, so \\(\\sigma=0\\) from bending.", src: "libretexts-mom", also: ["ncees-ref"] },
    { id: "fe066", ages: 'both', topic: "mom", s: "A beam section has I=\\(8.0\\times 10^{-6}\\,\\mathrm{m}^{4}\\) and c=\\(50\\,\\mathrm{mm}\\). The moment at the section is \\(40\\,\\mathrm{kN\\cdot m}\\). What is the maximum bending stress?", c: ["\\(125\\,\\mathrm{MPa}\\)", "\\(250\\,\\mathrm{MPa}\\)", "\\(80\\,\\mathrm{MPa}\\)", "\\(16\\,\\mathrm{MPa}\\)"], f: "\\(\\sigma=Mc/I=40\\times 10^{3}(0.050)/(8.0\\times 10^{-6})=2.50\\times 10^{8}\\) Pa \\(=250\\) MPa.", src: "libretexts-mom", also: ["ncees-ref"] },
    { id: "fe067", ages: 'both', topic: "mom", s: "For a material that stays linear and elastic, axial strain is:", c: ["Change in length divided by original length, inverted", "Change in length divided by original length", "Axial load acting on the section size", "Stress multiplied by the cross-section area"], f: "Average axial strain is the change in length divided by original length. Average axial strain is \\(\\varepsilon=\\delta/L\\). Hooke's law then gives \\(\\sigma=E\\varepsilon\\) in the linear range, but strain itself is a length ratio.", src: "libretexts-mom", also: ["ncees-ref"] },
    { id: "fe068", ages: 'both', topic: "mom", s: "A bar is heated by \\(\\Delta T\\) but is free to expand. The thermal stress is:", c: ["\\(E\\alpha\\Delta T\\)", "Zero", "\\(\\alpha\\Delta T\\)", "\\(E\\Delta T\\)"], f: "Thermal strain is \\(\\alpha\\Delta T\\), but if the bar is free, the expansion is not restrained and thermal stress is zero. Stress appears only when expansion is constrained.", src: "libretexts-mom", also: ["ncees-ref"] },
    { id: "fe069", ages: 'both', topic: "mom", s: "Principal stresses occur on planes where:", c: ["The normal stress is zero", "The shear stress is zero", "The moment is zero", "The strain energy is zero"], f: "Principal planes are defined as the orientations where shear stress is zero and the normal stress is a maximum or minimum (the principal stresses). Mohr's circle makes this visible: principals are the horizontal intercepts.", src: "libretexts-mom", also: ["ncees-ref"], img: "img/fe-mohr.svg", imgAlt: "Mohr's circle with the normal-stress axis labeled to the right of the origin and shear vertical, and a marked X-face point." },
    { id: "fe070", ages: 'both', topic: "mom", s: "A stress state has \\(\\sigma_x=80\\,\\mathrm{MPa}\\), \\(\\sigma_y=20\\,\\mathrm{MPa}\\), and \\(\\tau_{xy}=0\\). The principal stresses are:", c: ["\\(50\\,\\mathrm{MPa}\\) and \\(50\\,\\mathrm{MPa}\\)", "\\(80\\,\\mathrm{MPa}\\) and \\(20\\,\\mathrm{MPa}\\)", "\\(100\\,\\mathrm{MPa}\\) and 0", "\\(60\\,\\mathrm{MPa}\\) and \\(40\\,\\mathrm{MPa}\\)"], f: "With no shear, the given x and y stresses already are principal: \\(\\sigma_1=80\\) MPa, \\(\\sigma_2=20\\) MPa.", src: "libretexts-mom", also: ["ncees-ref"], img: "img/fe-mohr.svg", imgAlt: "Mohr's circle axes with a marked stress point; the normal-stress axis is labeled to the right of the origin." },
    { id: "fe071", ages: 'both', topic: "mom", s: "Poisson's ratio is the negative of which ratio, in the elastic range?", c: ["Axial strain over lateral strain, inverted", "Lateral strain over the axial strain", "Shear stress over shear strain", "Stress over strain"], f: "Poisson's ratio is \\(\\nu=-\\varepsilon_{lateral}/\\varepsilon_{axial}\\) for uniaxial loading in the elastic range, that is, lateral strain over the axial strain.", src: "libretexts-mom", also: ["ncees-ref"] },
    { id: "fe072", ages: 'both', topic: "mom", s: "A cantilever of length L has a point load P at the free end. The end deflection (EI constant) is:", c: ["\\(PL^{3}/(8EI)\\)", "\\(PL^{3}/(3EI)\\)", "\\(PL^{2}/(2EI)\\)", "\\(PL^{3}/EI\\)"], f: "The elastic deflection at the free end of a tip-loaded cantilever is \\(PL^{3}/(3EI)\\).", src: "libretexts-mom", also: ["ncees-ref"], img: "img/fe-cantilever.svg", imgAlt: "A horizontal cantilever, fixed at the left, with a downward point load P at the free end.", imgAsk: true },
    { id: "fe073", ages: 'both', topic: "materials", s: "In a concrete mix, the water-cement ratio most directly affects which property of the hardened concrete?", c: ["The color or texture of the paste alone", "Strength and durability", "The steel yield stress and grade", "The aggregate mineral name and color"], f: "A lower water-cement ratio generally gives higher strength and improved durability, provided the mix can still be placed and consolidated.", src: "fhwa-pavement", also: ["ncees-ref", "libretexts-mom"] },
    { id: "fe074", ages: 'both', topic: "materials", s: "The slump test on fresh concrete is used mainly to indicate:", c: ["The 28-day compressive strength of the hardened concrete", "Workability, or consistency, of the fresh mix", "Air content or unit weight to the nearest 0.01 percent", "The modulus of elasticity of the hardened concrete"], f: "Slump is a field test of consistency and workability of fresh concrete. Strength, air content, and E are measured with other tests.", src: "fhwa-pavement", also: ["ncees-ref", "libretexts-mom"] },
    { id: "fe075", ages: 'both', topic: "materials", s: "A steel coupon has a yield stress of \\(400\\,\\mathrm{MPa}\\). What is the yield load for a \\(500\\,\\mathrm{mm}^{2}\\) bar, if yield is based on that stress?", c: ["\\(400\\,\\mathrm{kN}\\)", "\\(200\\,\\mathrm{kN}\\)", "\\(80\\,\\mathrm{kN}\\)", "\\(0.8\\,\\mathrm{kN}\\)"], f: "Load is \\(P=\\sigma A=400\\,\\mathrm{N/mm}^{2}\\times 500\\,\\mathrm{mm}^{2}=200{,}000\\) N \\(=200\\) kN.", src: "libretexts-mom", also: ["ncees-ref"] },
    { id: "fe076", ages: 'both', topic: "materials", s: "Specific gravity of a soil solid is 2.70. What is the unit weight of the solids if the unit weight of water is \\(9.81\\,\\mathrm{kN}/\\mathrm{m}^{3}\\)?", c: ["\\(2.70\\,\\mathrm{kN}/\\mathrm{m}^{3}\\)", "\\(26.5\\,\\mathrm{kN}/\\mathrm{m}^{3}\\)", "\\(9.81\\,\\mathrm{kN}/\\mathrm{m}^{3}\\)", "\\(12.5\\,\\mathrm{kN}/\\mathrm{m}^{3}\\)"], f: "Unit weight of solids is \\(\\gamma_s=G_s\\gamma_w=2.70(9.81)=26.49\\) kN/m\\(^{3}\\), about \\(26.5\\,\\mathrm{kN}\\)/m\\(^{3}\\).", src: "libretexts-mom", also: ["ncees-ref"] },
    { id: "fe077", ages: 'both', topic: "materials", s: "The modulus of elasticity of a metal in the linear range is:", c: ["The peak stress on the curve, often called the tensile strength", "The slope of the linear stress-strain curve", "The region under the whole curve, a toughness measure", "The strain at fracture, past the linear range"], f: "E is the slope of the linear portion of the engineering stress-strain curve, that is, the slope of the linear stress-strain curve.", src: "libretexts-mom", also: ["ncees-ref"] },
    { id: "fe078", ages: 'both', topic: "materials", s: "Air-entrained concrete is used primarily to improve:", c: ["The yield strength of the reinforcing steel", "Resistance to the freeze-thaw damage", "How uniform the color of the formwork looks", "The elastic modulus of the reinforcing steel"], f: "Entrained air provides small, well-distributed voids that improve resistance to freeze-thaw damage in concrete. It is not a steel property.", src: "libretexts-mom", also: ["ncees-ref"] },
    { id: "fe079", ages: 'both', topic: "materials", s: "A wood member is graded and then used as a beam. Which strength property is typically the lowest?", c: ["Stress parallel to the grain, in the crushing direction", "Tension perpendicular to the grain, which is typically very low", "A steel-like yield plateau", "The modulus of elasticity compared with ordinary concrete"], f: "Wood is anisotropic. Tension perpendicular to the grain is typically much lower than parallel-to-grain tension or compression, and NDS practice is to detail around that weak direction rather than rely on it.", src: "awc-nds", also: ["ncees-ref"] },
    { id: "fe080", ages: 'both', topic: "materials", s: "The Marshall mix method is used in the design of which paving material?", c: ["Portland cement grout by itself", "Asphalt concrete", "Structural steel welds", "Tempered glass"], f: "The Marshall method is a laboratory design procedure for asphalt concrete. The Marshall method is a traditional laboratory design procedure for hot-mix asphalt, relating stability, flow, and voids. It is not a steel or glass test.", src: "fhwa-pavement", also: ["ncees-ref", "libretexts-mom"] },
    { id: "fe081", ages: 'both', topic: "materials", s: "A metal specimen has a \\(50\\,\\mathrm{mm}\\) gage length and stretches \\(0.10\\,\\mathrm{mm}\\) in the elastic range. What is the axial strain?", c: ["0.10", "0.0020", "0.0050", "2.0"], f: "Strain is \\(\\varepsilon=\\delta/L=0.0020\\) (dimensionless).", src: "libretexts-mom", also: ["ncees-ref"] },
    { id: "fe082", ages: 'both', topic: "materials", s: "Aggregates for concrete should be:", c: ["As dirty as possible, so extra clay can act as binder", "Clean, well graded, and free of harmful fines", "A single particle size, used in each mix and batch", "Made of clay lumps and organic soil"], f: "Good aggregates are clean, well graded, and free of harmful fines so the mix is economical and durable. Clay, organics, and excess fines can hurt strength and durability.", src: "fhwa-pavement", also: ["ncees-ref", "libretexts-mom"] },
    { id: "fe083", ages: 'both', topic: "fluids", s: "The gage pressure at a depth of 5.0 m in fresh water is most nearly which value? Use \\(\\gamma=9.81\\,\\mathrm{kN}/\\mathrm{m}^{3}\\).", c: ["9.81 kPa", "49.1 kPa", "24.5 kPa", "5.00 kPa"], f: "Hydrostatic gage pressure is \\(p=\\gamma h=9.81(5.0)=49.05\\) kPa, about 49.1 kPa. Using \\(\\rho h\\) without g, or using 10 m, are common errors.", src: "openstax-up1", also: ["ncees-ref"] },
    { id: "fe084", ages: 'both', topic: "fluids", s: "A fluid has density \\(800\\,\\mathrm{kg}/\\mathrm{m}^{3}\\). What is its specific gravity?", c: ["800", "0.80", "7.85", "1.80"], f: "Specific gravity is \\(SG=\\rho/\\rho_w=0.80\\).", src: "openstax-up1", also: ["ncees-ref"] },
    { id: "fe085", ages: 'both', topic: "fluids", s: "Water flows at \\(2.0\\,\\mathrm{m/s}\\) in a \\(0.10\\,\\mathrm{m}\\) diameter pipe. What is the discharge Q?", c: ["\\(0.200\\,\\mathrm{m}^{3}/\\mathrm{s}\\)", "\\(0.0157\\,\\mathrm{m}^{3}/\\mathrm{s}\\)", "\\(0.628\\,\\mathrm{m}^{3}/\\mathrm{s}\\)", "\\(0.0314\\,\\mathrm{m}^{3}/\\mathrm{s}\\)"], f: "\\(Q=VA=V(\\pi d^{2}/4)=2.0(\\pi(0.10)^{2}/4)=0.0157\\) m\\(^{3}\\)/s. Using diameter as radius, or forgetting \\(\\pi/4\\), causes large errors.", src: "openstax-up1", also: ["ncees-ref"] },
    { id: "fe086", ages: 'both', topic: "fluids", s: "Bernoulli's equation along a streamline for steady, incompressible, frictionless flow conserves which quantity?", c: ["Mechanical energy per unit length, also called the head", "Mechanical energy per unit weight, also called the head", "Mechanical energy per unit time, also called the head", "Mechanical energy per unit volume, also called the head"], f: "Bernoulli states \\(p/\\gamma+V^{2}/(2g)+z\\) is constant along a streamline under those assumptions. That combination is mechanical energy per unit weight, also called the head.", src: "openstax-up1", also: ["ncees-ref"], img: "img/fe-pipe.svg", imgAlt: "A pipe running from a higher point A to a lower point B, with elevation difference z." },
    { id: "fe087", ages: 'both', topic: "fluids", s: "A pitot tube in an open airstream is used primarily to measure:", c: ["Flow speed, from the free-stream temperature and humidity", "Flow speed, from the stagnation and static pressures", "Flow speed, from the mass density and a scale sample", "Flow speed, from the wall thickness and a shop log"], f: "A pitot (or pitot-static) tube uses the difference between stagnation and static pressure: \\(V=\\sqrt{2\\Delta p/\\rho}\\). It is used to measure flow speed from the stagnation and static pressures.", src: "openstax-up1", also: ["ncees-ref"] },
    { id: "fe088", ages: 'both', topic: "fluids", s: "The Reynolds number is used to:", c: ["Compute hydrostatic pressure at a free surface", "Judge whether the flow is laminar or turbulent", "Leave the continuity equation aside in the control-volume statement", "Give the vapor pressure of water"], f: "\\(Re=\\rho VD/\\mu\\) (or \\(VD/\\nu\\)) compares inertia to viscosity and is the usual test used to judge whether flow is laminar or turbulent.", src: "openstax-up1", also: ["ncees-ref"] },
    { id: "fe089", ages: 'both', topic: "fluids", s: "Water flows in a 2.0 m wide rectangular channel at a depth of \\(0.50\\,\\mathrm{m}\\) and a speed of \\(1.2\\,\\mathrm{m/s}\\). What is Q?", c: ["\\(0.90\\,\\mathrm{m}^{3}/\\mathrm{s}\\)", "\\(1.20\\,\\mathrm{m}^{3}/\\mathrm{s}\\)", "\\(0.60\\,\\mathrm{m}^{3}/\\mathrm{s}\\)", "\\(0.40\\,\\mathrm{m}^{3}/\\mathrm{s}\\)"], f: "For a rectangle, \\(A=by=2.0(0.50)=1.0\\) m\\(^{2}\\), so \\(Q=VA=1.2(1.0)=1.20\\) m\\(^{3}\\)/s.", src: "openstax-up1", also: ["ncees-ref"], img: "img/fe-channel.svg", imgAlt: "A rectangular open channel of width b with water depth y.", imgAsk: true },
    { id: "fe090", ages: 'both', topic: "fluids", s: "Manning's equation for uniform open-channel flow gives discharge as \\(Q=\\frac{1}{n}AR^{2/3}S^{1/2}\\) (SI). The n term is:", c: ["The Reynolds number", "A roughness coefficient", "The hydraulic jump height", "The saturation pressure of the fluid"], f: "Manning's n is an empirical roughness coefficient. Larger n means more resistance and less discharge for the same area, hydraulic radius, and slope.", src: "openstax-up1", also: ["ncees-ref"], img: "img/fe-channel.svg", imgAlt: "A rectangular open channel with labeled width and depth." },
    { id: "fe091", ages: 'both', topic: "fluids", s: "A rectangular channel is 2.0 m wide and flows 0.50 m deep. What is the hydraulic radius R=A/P?", c: ["0.500 m", "0.333 m", "1.00 m", "0.250 m"], f: "Area \\(A=2.0(0.50)=1.0\\) m\\(^{2}\\). Wetted perimeter \\(P=2.0+2(0.50)=3.0\\) m. Then \\(R=A/P=1/3=0.333\\) m. Using depth as R is a common error.", src: "openstax-up1", also: ["ncees-ref"], img: "img/fe-channel.svg", imgAlt: "A rectangular open channel of width b and depth y.", imgAsk: true },
    { id: "fe092", ages: 'both', topic: "fluids", s: "The hydrostatic force on one side of a vertical rectangular gate, height h and width b, with the top edge at the free surface, has a magnitude of:", c: ["\\(\\gamma b^{2}h/2\\)", "\\(\\gamma bh^{2}/2\\)", "\\(\\gamma bh^{2}/4\\)", "\\(2\\gamma bh^{2}\\)"], f: "The pressure is triangular: average pressure is \\(\\gamma h/2\\), area is \\(bh\\), so \\(F=(\\gamma h/2)bh=\\gamma b h^{2}/2\\). The resultant acts at \\(2h/3\\) from the free surface.", src: "openstax-up1", also: ["ncees-ref"] },
    { id: "fe093", ages: 'both', topic: "fluids", s: "A jet of water with speed \\(10\\,\\mathrm{m/s}\\) and area \\(0.010\\,\\mathrm{m}^{2}\\) strikes a flat plate and is stopped. What is the force on the plate? Use \\(\\rho=1000\\,\\mathrm{kg}/\\mathrm{m}^{3}\\).", c: ["100 N", "1,000 N", "10 N", "10,000 N"], f: "Momentum: \\(F=\\rho Q V=\\rho A V^{2}=1000(0.010)(10)^{2}=1,000\\) N when the exit velocity along the jet axis is reduced to zero.", src: "openstax-up1", also: ["ncees-ref"] },
    { id: "fe094", ages: 'both', topic: "fluids", s: "Absolute pressure equals gage pressure plus:", c: ["Saturation pressure by itself", "The atmospheric pressure", "Dynamic pressure by itself", "Zero, in each reading"], f: "Absolute pressure equals gage pressure plus atmospheric pressure. By definition, \\(p_{abs}=p_{gage}+p_{atm}\\). Vacuum (negative gage) still converts the same way.", src: "openstax-up1", also: ["ncees-ref"] },
    { id: "fe095", ages: 'both', topic: "surveying", s: "A line has a bearing of N 30° E. What is its azimuth from north, clockwise?", c: ["60 degrees", "30 degrees", "150 degrees", "330 degrees"], f: "Azimuth is measured clockwise from north. N 30° E is 30 degrees from north toward east, so the azimuth is 30 degrees.", src: "ngs", also: ["ncees-spec"] },
    { id: "fe096", ages: 'both', topic: "surveying", s: "A 200 m course has an azimuth of 90°. What are the latitude (northing change) and departure (easting change)?", c: ["Latitude 200 m, departure 0 m", "Latitude 0 m, departure 200 m", "Latitude 141 m, departure 141 m", "Latitude -200 m, departure 0 m"], f: "Latitude is \\(L\\cos(az)\\), departure is \\(L\\sin(az)\\). At 90° (due east), latitude is 0 m and departure is 200 m.", src: "ngs", also: ["ncees-spec"] },
    { id: "fe097", ages: 'both', topic: "surveying", s: "A grade of 4% means a rise of:", c: ["4 meters in 1 meter of run", "4 meters in 100 meters of horizontal distance", "A 1-to-1 slope, meaning 4 meters in 4 meters of run", "0.4 meters in 100 meters"], f: "Percent grade is rise over run times 100. A 4% grade is 4 meters of rise in 100 meters of horizontal distance.", src: "ngs", also: ["ncees-spec"] },
    { id: "fe098", ages: 'both', topic: "surveying", s: "In differential leveling, a backsight (BS) of 1.52 m is taken on BM A (elevation 100.00 m). A foresight (FS) of 2.10 m is taken on point B. What is the elevation of B?", c: ["100.58 m", "99.42 m", "103.62 m", "98.48 m"], f: "HI = elevation + BS = 100.00+1.52=101.52 m. Elevation of B is HI - FS = 101.52-2.10=99.42 m. Adding FS would raise the point wrongly.", src: "ngs", also: ["ncees-spec"], img: "img/fe-level.svg", imgAlt: "A level set between point A and point B, with a backsight on A and a foresight on B.", imgAsk: true },
    { id: "fe099", ages: 'both', topic: "surveying", s: "The area of a triangular parcel with base 80 m and height 30 m is:", c: ["\\(2,400\\,\\mathrm{m}^{2}\\)", "\\(1,200\\,\\mathrm{m}^{2}\\)", "\\(110\\,\\mathrm{m}^{2}\\)", "\\(800\\,\\mathrm{m}^{2}\\)"], f: "Area is \\(\\frac{1}{2}bh=\\frac{1}{2}(80)(30)=1,200\\) m\\(^{2}\\).", src: "ngs", also: ["ncees-spec"] },
    { id: "fe100", ages: 'both', topic: "surveying", s: "The average-end-area method for earthwork volume between two stations is:", c: ["\\(V\\) is the product of \\(L\\), \\(A_1\\), and \\(A_2\\)", "\\(V = L (A_1 + A_2) / 2\\)", "\\(V = (A_1 + A_2) / L\\)", "\\(V = L^{2} (A_1 + A_2)\\)"], f: "Average-end-area is \\(V=L(A_1+A_2)/2\\). The prismoidal formula adds a mid-area term and is more accurate for some shapes.", src: "ngs", also: ["ncees-spec"] },
    { id: "fe101", ages: 'both', topic: "surveying", s: "End areas 30 m apart are \\(40\\,\\mathrm{m}^{2}\\) and \\(60\\,\\mathrm{m}^{2}\\). Using average end area, what is the volume?", c: ["\\(3,000\\,\\mathrm{m}^{3}\\)", "\\(1,500\\,\\mathrm{m}^{3}\\)", "\\(1,200\\,\\mathrm{m}^{3}\\)", "\\(100\\,\\mathrm{m}^{3}\\)"], f: "\\(V=L(A_1+A_2)/2=30(40+60)/2=1,500\\) m\\(^{3}\\).", src: "ngs", also: ["ncees-spec"] },
    { id: "fe102", ages: 'both', topic: "surveying", s: "A state plane coordinate system is used mainly to:", c: ["Leave latitude and longitude aside in favor of a spherical grid", "Provide a plane grid with limited distortion for the region", "Measure time zones", "Establish mean sea level in mid-ocean"], f: "State plane systems provide a plane grid for a region, mapping a portion of the Earth onto a plane (Lambert or transverse Mercator) so surveyors can use plane coordinates with limited distortion. They do not replace geodetic control entirely.", src: "ngs", also: ["ncees-spec"] },
    { id: "fe103", ages: 'both', topic: "surveying", s: "A 150 m tape is used on a 3% grade, but the tape length is taken as horizontal. The true horizontal distance is most nearly:", c: ["150.00 m", "149.93 m", "154.50 m", "145.50 m"], f: "Horizontal distance is \\(L\\cos\\theta\\), and \\(\\tan\\theta=0.03\\) so \\(\\theta=\\arctan 0.03\\). Then \\(150\\cos(\\arctan 0.03)=149.93\\) m. The correction is about \\(L(g^{2}/2)\\) for small grades.", src: "ngs", also: ["ncees-spec"] },
    { id: "fe104", ages: 'both', topic: "surveying", s: "Interior angles of a closed five-sided polygon (pentagon) should sum to:", c: ["360 degrees", "540 degrees", "720 degrees", "180 degrees"], f: "The sum of interior angles of an n-sided closed polygon is \\((n-2)180^{\\circ}=540\\) degrees.", src: "ngs", also: ["ncees-spec"] },
    { id: "fe105", ages: 'both', topic: "surveying", s: "A road rises 8 m over a 200 m horizontal distance. What is the percent grade?", c: ["8%", "4%", "6%", "40%"], f: "Percent grade is rise over run, times 100, which is 4%.", src: "ngs", also: ["ncees-spec"] },
    { id: "fe106", ages: 'both', topic: "surveying", s: "Which statement about a local north-south line is true?", c: ["A meridian runs east-west, like a parallel or standard of latitude", "A meridian is a north-south line used for the bearings and azimuths", "Azimuths cannot be measured from north and south", "Latitude is an easting coordinate in meters and a state-plane grid"], f: "A meridian is a north-south reference. Bearings and azimuths are measured from that north-south line. Parallels run east-west and represent latitude.", src: "ngs", also: ["ncees-spec"] },
    { id: "fe107", ages: 'both', topic: "water", s: "The rational method peak runoff is \\(Q=CiA\\). The C term is:", c: ["Chezy's coefficient", "A runoff coefficient", "The catchment area in acres, in each case", "A pipe roughness"], f: "In the rational method, \\(C\\) is a dimensionless runoff coefficient (fraction of rainfall that becomes peak runoff). \\(i\\) is rainfall intensity and \\(A\\) is drainage area, in consistent units.", src: "fhwa-hec22", also: ["usgs-water", "ncees-ref"] },
    { id: "fe108", ages: 'both', topic: "water", s: "A 2.0 acre parking lot has C=0.90. Rainfall intensity is 3.0 in/hr. Using Q=CiA (cfs, with A in acres and i in in/hr), what is Q?", c: ["6.0 cfs", "5.4 cfs", "1.8 cfs", "0.54 cfs"], f: "With those units, \\(Q=CiA=0.90(3.0)(2.0)=5.4\\) cfs.", src: "fhwa-hec22", also: ["usgs-water", "ncees-ref"] },
    { id: "fe109", ages: 'both', topic: "water", s: "Manning's equation can be used for which of the following in a long, uniform channel?", c: ["Unsteady dam-break fronts by themselves", "Normal-depth flow (uniform flow)", "Groundwater drawdown in an aquifer", "BOD removal in a reactor"], f: "Manning's formula is for uniform, or normal-depth, open-channel flow, relating discharge to roughness, area, hydraulic radius, and slope.", src: "usgs-water", also: ["ncees-ref"] },
    { id: "fe110", ages: 'both', topic: "water", s: "A rectangular channel is 2.0 m wide, flowing 1.00 m deep, with S=0.001 and n=0.013. Using Manning in SI, what is Q?", c: ["\\(1.92\\,\\mathrm{m}^{3}/\\mathrm{s}\\)", "\\(3.06\\,\\mathrm{m}^{3}/\\mathrm{s}\\)", "\\(0.61\\,\\mathrm{m}^{3}/\\mathrm{s}\\)", "\\(2.40\\,\\mathrm{m}^{3}/\\mathrm{s}\\)"], f: "\\(A=2.00\\) m\\(^{2}\\), \\(P=4.00\\) m, \\(R=0.50\\) m. \\(Q=\\frac{1}{n}AR^{2/3}S^{1/2}=\\frac{1}{0.013}(2)(0.50)^{2/3}(0.001)^{1/2}=3.06\\) m\\(^{3}\\)/s.", src: "usgs-water", also: ["ncees-ref"], img: "img/fe-channel.svg", imgAlt: "A rectangular open channel with width b and depth y.", imgAsk: true },
    { id: "fe111", ages: 'both', topic: "water", s: "Darcy's law for one-dimensional flow through soil is \\(q=k i\\). The i term is:", c: ["The Reynolds number of the seepage, used to classify the flow regime", "The hydraulic gradient, or head loss per unit length", "The porosity or void ratio of the soil, used in volume relations", "The unit weight of water, used in pressure calculations"], f: "Darcy's law is \\(q=k i=k(\\Delta h/L)\\), where \\(k\\) is hydraulic conductivity and \\(i\\) is the hydraulic gradient. The gradient i in Darcy's law is the hydraulic gradient, or head loss per unit length. Discharge through area A is \\(Q=k i A\\).", src: "usgs-water", also: ["ncees-ref"] },
    { id: "fe112", ages: 'both', topic: "water", s: "A soil sample has \\(k=0.001\\,\\mathrm{cm/s}\\), a hydraulic gradient of 0.20, and a cross section of \\(50\\,\\mathrm{cm}^{2}\\). What is Q?", c: ["\\(0.001\\,\\mathrm{cm}^{3}/\\mathrm{s}\\)", "\\(0.010\\,\\mathrm{cm}^{3}/\\mathrm{s}\\)", "\\(0.10\\,\\mathrm{cm}^{3}/\\mathrm{s}\\)", "\\(10\\,\\mathrm{cm}^{3}/\\mathrm{s}\\)"], f: "\\(Q=k i A=0.001(0.20)(50)=0.010\\) cm\\(^{3}\\)/s. Keep units consistent.", src: "usgs-water", also: ["ncees-ref"] },
    { id: "fe113", ages: 'both', topic: "water", s: "A pump moves \\(0.050\\,\\mathrm{m}^{3}/\\mathrm{s}\\) of water against 20 m of head. If the pump efficiency is 80%, what input power is required? Use \\(\\gamma=9.81\\,\\mathrm{kN}/\\mathrm{m}^{3}\\).", c: ["9.81 kW", "12.3 kW", "15.4 kW", "1.00 kW"], f: "Shaft (input) power is 12.3 kW after dividing water power by the pump efficiency.", src: "openstax-up1", also: ["usgs-water", "ncees-ref"] },
    { id: "fe114", ages: 'both', topic: "water", s: "In a municipal water distribution system, residual pressure at hydrants is needed mainly to:", c: ["Raise the vapor pressure of the water in the mains", "Deliver the needed fire and domestic flow", "Leave the plant's water-treatment process and residuals aside in the design", "Regard pipe material selection and lining as optional for the system"], f: "Distribution systems are sized and operated to deliver needed fire and domestic flow while keeping residual pressures acceptable. Pressure does not replace treatment.", src: "epa-drinking", also: ["usgs-water", "ncees-ref"] },
    { id: "fe115", ages: 'both', topic: "water", s: "A detention basin is used in stormwater design primarily to:", c: ["Raise the peak runoff leaving a developed site", "Store the runoff and release it more slowly", "Remove the dissolved minerals and salts from the runoff", "Regard inlet structures and outlets as optional on the developed site"], f: "Detention (and similar storage) is used to store runoff and release it more slowly, cutting the peak outflow and often improving downstream flooding and quality control.", src: "fhwa-hec22", also: ["usgs-water", "ncees-ref"] },
    { id: "fe116", ages: 'both', topic: "water", s: "The time of concentration of a watershed is:", c: ["The length of the longest drought in the historic record for that basin", "Travel time from the most remote hydraulic point to the outlet", "The time needed to fill a water tower from empty", "The hydraulic residence time in a treatment plant"], f: "It is used to pick a duration and intensity in methods such as the rational method. Time of concentration is the travel time from the hydraulically most remote point of the basin to the outlet.", src: "fhwa-hec22", also: ["usgs-water", "ncees-ref"] },
    { id: "fe117", ages: 'both', topic: "water", s: "A confined aquifer well is pumped, and the water level in a nearby observation well drops. That drop is called:", c: ["Porosity", "The drawdown", "Specific gravity", "Slump"], f: "Drawdown is the lowering of the piezometric surface (or water table in an unconfined aquifer) due to pumping. It is used with aquifer tests (Thiem or Theis) to estimate transmissivity and storage.", src: "usgs-water", also: ["ncees-ref"] },
    { id: "fe118", ages: 'both', topic: "water", s: "Hardness in water is caused mainly by which ions?", c: ["Sodium and potassium by themselves", "Calcium and magnesium", "Chloride and fluoride by themselves", "Dissolved oxygen and nitrogen"], f: "Hardness is due primarily to calcium and magnesium. Softening processes (lime-soda or ion exchange) target those ions.", src: "usgs-water", also: ["ncees-ref"] },
    { id: "fe119", ages: 'both', topic: "water", s: "BOD in wastewater is a measure of:", c: ["Hardness, expressed as calcium carbonate", "Oxygen demand from the biodegradable organic matter", "Turbidity in NTU", "The vapor pressure of the wastewater sample"], f: "Biochemical oxygen demand measures the oxygen used by microorganisms as they oxidize biodegradable organic matter. It is a key strength measure for wastewater.", src: "epa-wastewater", also: ["usgs-water", "ncees-ref"] },
    { id: "fe120", ages: 'both', topic: "water", s: "A common first process in conventional drinking-water treatment for a surface supply is:", c: ["Reverse osmosis and membrane filtration, then disinfection and storage", "Coagulation and flocculation, then settling and filtration", "Activated-sludge aeration and mixing as an early drinking-water step", "Land application of raw river water and sewage"], f: "Conventional surface-water treatment typically includes coagulation, flocculation, sedimentation, filtration, and disinfection. Activated sludge is a wastewater process.", src: "epa-drinking", also: ["usgs-water", "ncees-ref"] },
    { id: "fe121", ages: 'both', topic: "water", s: "A spillway is provided on a dam mainly to:", c: ["Raise seepage through the dam foundation", "Pass flood flows safely so the dam is not overtopped", "Store water inside the pipe gallery", "Regard outlet works as optional on each dam"], f: "A spillway is a flood-release structure that protects the dam from uncontrolled overtopping. A spillway is intended to pass flood flows safely so the dam is not overtopped. Outlet works are a separate, usually gated, release system.", src: "usgs-water", also: ["ncees-ref"] },
    { id: "fe122", ages: 'both', topic: "water", s: "Sanitary sewer systems are designed mainly to carry:", c: ["Roof runoff, and not wastewater, inside a sanitary sewer", "Wastewater and some infiltration, not stormwater, in a separate system", "Groundwater and irrigation return, excluding sewage", "High-pressure potable water and fire flow"], f: "In a separate sewer system, sanitary sewers carry wastewater and some infiltration, not stormwater, while storm sewers carry runoff. Combined systems carry both, but modern design often keeps them separate.", src: "epa-waste", also: ["usgs-water", "ncees-ref"] },
    { id: "fe123", ages: 'both', topic: "water", s: "A 4.0 km gravity sewer has a drop of 8.0 m. What is the average slope?", c: ["0.020", "0.0020", "2.0", "0.00050"], f: "Slope is \\(S=\\Delta z/L=8.0/(4000)=0.0020\\). Forgetting to convert km to m gives a 1000-times error.", src: "epa-waste", also: ["usgs-water", "ncees-ref"] },
    { id: "fe124", ages: 'both', topic: "water", s: "The runoff hydrograph from a watershed is:", c: ["A plot of soil grain size", "Discharge at the outlet versus time", "A pump curve of head versus efficiency", "A map of water-quality sampling sites"], f: "A hydrograph is a plot of streamflow (or runoff discharge) versus time at a location, often the basin outlet. Unit hydrographs are a scaled form used in hydrology.", src: "epa-waste", also: ["usgs-water", "ncees-ref"] },
    { id: "fe125", ages: 'both', topic: "water", s: "A coagulation process in water treatment is intended to:", c: ["Sterilize pipes with high heat after a main break", "Destabilize colloids so they can flocculate and be removed", "Remove settleable grit and sand in a deep grit chamber", "Raise the pH above 12 as a standalone process"], f: "Coagulants (often aluminum or iron salts) destabilize colloids so they can flocculate and be removed on filters or in settling tanks. Disinfection, not coagulation, is the primary microbial kill step.", src: "epa-waste", also: ["usgs-water", "ncees-ref"] },
    { id: "fe126", ages: 'both', topic: "water", s: "Infiltration of rainfall into soil is reduced when:", c: ["The soil is dry, sandy, and deeply permeable, in every such event", "The soil is already wet, frozen, or sealed by intense rain", "There is zero rainfall on the watershed", "The air temperature is used as a hydraulic conductivity"], f: "Infiltration capacity drops as soil wets up, if a crust forms, or if the ground is frozen. Infiltration capacity drops when the soil is already wet, frozen, or sealed by intense rain. Dry, permeable soils generally infiltrate more, not less.", src: "epa-waste", also: ["usgs-water", "ncees-ref"] },
    { id: "fe127", ages: 'both', topic: "structural", s: "A simply supported beam with a midspan point load P and span L has a maximum shear of:", c: ["P", "\\(P/2\\)", "\\(P/4\\)", "\\(PL/4\\)"], f: "Each support carries \\(P/2\\), which is also the maximum shear between the support and the load.", src: "libretexts-mom", also: ["ncees-ref"], img: "img/fe-beam-mid.svg", imgAlt: "Simply supported beam with a midspan point load P.", imgAsk: true },
    { id: "fe128", ages: 'both', topic: "structural", s: "The midspan deflection of a simply supported beam with midspan point load P (EI constant) is:", c: ["\\(PL^{3}/(3EI)\\)", "\\(PL^{3}/(48EI)\\)", "\\(PL^{3}/(8EI)\\)", "\\(PL^{2}/(16EI)\\)"], f: "The standard midspan result is \\(\\delta_{mid}=PL^{3}/(48EI)\\).", src: "libretexts-mom", also: ["ncees-ref"], img: "img/fe-beam-mid.svg", imgAlt: "Simply supported beam with a concentrated midspan load." },
    { id: "fe129", ages: 'both', topic: "structural", s: "Euler buckling load for a pinned-pinned column is \\(P_{cr}=\\pi^{2} EI/L^{2}\\). If the length is doubled and all else is unchanged, \\(P_{cr}\\) becomes:", c: ["Twice as large", "One fourth as large", "Four times as large", "Unchanged"], f: "Doubling the pinned length makes the Euler load one fourth as large. Because \\(P_{cr}\\) varies as \\(1/L^{2}\\), doubling L divides \\(P_{cr}\\) by 4. End conditions change the effective length, but here they stay pinned-pinned.", src: "libretexts-mom", also: ["ncees-ref"], img: "img/fe-column.svg", imgAlt: "A straight column with pin supports at both ends and an axial load P.", imgAsk: true },
    { id: "fe130", ages: 'both', topic: "structural", s: "A pinned-pinned steel column has E=\\(200\\,\\mathrm{GPa}\\), I=\\(8.0\\times 10^{-6}\\,\\mathrm{m}^{4}\\), and L=4.0 m. What is the Euler load?", c: ["\\(99\\,\\mathrm{kN}\\)", "\\(987\\,\\mathrm{kN}\\)", "\\(396\\,\\mathrm{kN}\\)", "\\(500\\,\\mathrm{kN}\\)"], f: "\\(P_{cr}=\\pi^{2} EI/L^{2}=\\pi^{2}(200\\times 10^{9})(8.0\\times 10^{-6})/16=9.87\\times 10^{5}\\) N \\(\\approx 987\\) kN.", src: "libretexts-mom", also: ["ncees-ref"], img: "img/fe-column.svg", imgAlt: "A pinned-pinned column of length L under axial load P.", imgAsk: true },
    { id: "fe131", ages: 'both', topic: "structural", s: "A structure is statically determinate if:", c: ["It has at least one redundant member or support, so equilibrium is not enough", "Reactions and internal forces can be found from equilibrium alone", "It cannot carry a load, so it is a mechanism", "It is a statically indeterminate beam and frame by definition"], f: "A determinate structure has a number of unknowns equal to the independent equilibrium equations, so equilibrium is enough. On a statically determinate structure, reactions and internal forces can be found from equilibrium alone. Extra unknowns are redundants and need deformation conditions.", src: "libretexts-mom", also: ["ncees-ref"] },
    { id: "fe132", ages: 'both', topic: "structural", s: "A plane truss has 6 joints and 9 members, and is supported by 3 reaction components. Using \\(m+r \\stackrel{?}{=} 2j\\), the truss is:", c: ["Unstable for any arrangement of the members", "Statically determinate, if the truss is stable", "Indeterminate to the third degree", "A mechanism with two degrees of freedom"], f: "The test is \\(m+r=2j\\). Here \\(9+3=12\\) and \\(2j=12\\), so the truss is statically determinate if it is properly arranged (stable).", src: "libretexts-mom", also: ["ncees-ref"] },
    { id: "fe133", ages: 'both', topic: "structural", s: "The tributary width for a typical interior beam spaced 4 m from similar beams on each side, spanning a uniform floor, is:", c: ["6 m", "4 m", "8 m", "10 m"], f: "For equally spaced similar beams, tributary width is the spacing, 4 m, half the distance to each neighbor.", src: "libretexts-mom", also: ["ncees-ref"] },
    { id: "fe134", ages: 'both', topic: "structural", s: "Dead load is best described as:", c: ["Occupancy live load from people, furniture, and movable contents", "The weight of the structure and permanently attached items", "Wind pressure on walls and other windward surfaces", "The earthquake inertial load on the seismic mass and foundation"], f: "Dead load is the self-weight of the structure and other permanently attached items. Live load covers occupancy and moveable items. Wind is a separate environmental load.", src: "libretexts-mom", also: ["ncees-ref"] },
    { id: "fe135", ages: 'both', topic: "structural", s: "In LRFD-type load combinations, live load and dead load are typically:", c: ["Subtracted from one another, as unfactored working values", "Factored, then combined using the specified load combinations", "Kept in separate equations and left uncombined", "Taken as zero for each building type"], f: "Strength design uses factored combinations (for example 1.2D+1.6L in many U.S. rules), then combines those factored loads with the specified load combinations. The factors and companion loads come from the governing standard, which must be consulted for a real design.", src: "libretexts-mom", also: ["ncees-ref"] },
    { id: "fe136", ages: 'both', topic: "structural", s: "A steel tension member is designed mainly for:", c: ["Euler buckling of a slender compressive member, a stability check", "Yielding of the gross section and fracture of the net section", "Torsion of a closed tube, and a different limit state", "Bearing on a concrete footing, a support and bearing check"], f: "Tension members are checked for yielding of the gross section and fracture of the net section (and for block shear at connections). Euler buckling applies to compression, not tension.", src: "libretexts-mom", also: ["ncees-ref"] },
    { id: "fe137", ages: 'both', topic: "structural", s: "A short, stocky reinforced-concrete column is typically controlled by:", c: ["Elastic Euler buckling, often called a slender-column limit", "Material strength, often called the squash load", "Lateral-torsional buckling, often called an unbraced-beam limit", "Plastic moment capacity, often called a compact-girder limit"], f: "Short columns reach a crushing or squash capacity based on concrete and steel strengths. A short column is limited by material strength, often called the squash load. Longer columns need additional moment magnification or second-order analysis.", src: "libretexts-mom", also: ["ncees-ref"] },
    { id: "fe138", ages: 'both', topic: "structural", s: "The internal shear just to the left of a midspan point load on a simple beam of span L and load P is:", c: ["Zero shear on the left segment, toward the midspan load", "\\(P/2\\) on the left segment, toward the midspan load", "\\(PL/4\\) on the left segment, toward the midspan load", "\\(P\\) on the left segment, toward the midspan load"], f: "Shear is \\(+P/2\\) (or \\(-P/2\\), depending on sign convention) on the left segment toward the midspan load, and it jumps by P at the load.", src: "libretexts-mom", also: ["ncees-ref"], img: "img/fe-beam-mid.svg", imgAlt: "Simply supported beam with a midspan point load." },
    { id: "fe139", ages: 'both', topic: "structural", s: "A fixed-end beam (both ends clamped) with a midspan point load is:", c: ["Statically determinate, with two support reactions", "Statically indeterminate", "A truss, carrying axial force", "Unstable, and unable to develop moments"], f: "A single-span beam with two fixed ends has four reaction components (two forces and two moments) but only three equilibrium equations in plane, so it is indeterminate. That beam is statically indeterminate. Extra conditions come from compatibility (zero end slopes).", src: "libretexts-mom", also: ["ncees-ref"] },
    { id: "fe140", ages: 'both', topic: "structural", s: "Lateral-torsional buckling is a concern mainly for:", c: ["Short concrete walls loaded in bearing, a compressive-wall example", "Slender, unbraced steel beams bent about the strong axis", "Cables that carry pure tension and cannot take compression", "Circular shafts loaded in torsion, a shaft design case"], f: "I-shaped steel beams can buckle laterally and twist between brace points under flexure. Lateral-torsional buckling mainly concerns slender, unbraced steel beams bent about the strong axis. Tension cables and many compact, well-braced members are not controlled by LTB.", src: "libretexts-mom", also: ["ncees-ref"] },
    { id: "fe141", ages: 'both', topic: "structural", s: "A 6 m simple beam carries a uniform \\(10\\,\\mathrm{kN}\\)/m load. What is the maximum moment?", c: ["\\(30\\,\\mathrm{kN\\cdot m}\\)", "\\(45\\,\\mathrm{kN\\cdot m}\\)", "\\(36\\,\\mathrm{kN\\cdot m}\\)", "\\(15\\,\\mathrm{kN\\cdot m}\\)"], f: "\\(M_{max}=wL^{2}/8=10(6)^{2}/8=45\\) kN·m. Using \\(wL^{2}/4=90\\) is a common error.", src: "libretexts-mom", also: ["ncees-ref"], img: "img/fe-beam-udl.svg", imgAlt: "Simply supported beam with a uniform load over the full span.", imgAsk: true },
    { id: "fe142", ages: 'both', topic: "structural", s: "The influence line for a simple-beam reaction at A is:", c: ["A parabola from 1 at A to 0 at B", "A straight line from 1 at A to 0 at B", "A constant run from 1 at A to 0 at B", "A triangle from 1 at A to 0 at B"], f: "By the definition of influence lines (or Muller-Breslau), unit load at A produces reaction 1 at A, and unit load at B produces reaction 0 at A, with a straight line in between for a determinate beam.", src: "libretexts-mom", also: ["ncees-ref"] },
    { id: "fe143", ages: 'both', topic: "structural", s: "A steel wide-flange beam is compact and fully braced. Flexural design is then often limited by:", c: ["The torsional constant of the section alone", "The plastic moment capacity of the section", "The tensile rupture strength of a gusset plate", "The Euler load of an equivalent pinned column"], f: "A compact, fully braced I-beam can form a plastic hinge and is limited by the plastic moment capacity of the section, \\(M_p=F_y Z\\) (with the resistance factor in LRFD). LTB and local buckling are kept from controlling by compactness and bracing.", src: "libretexts-mom", also: ["ncees-ref"] },
    { id: "fe144", ages: 'both', topic: "structural", s: "In a reinforced-concrete beam, tension steel is placed:", c: ["Near the top fiber in a simple span", "Near the face that is in tension under the design moment", "Near the compression face in each span, ignoring moment sign", "In the middle of the web, at mid-depth"], f: "Concrete is weak in tension, so flexural reinforcement is placed near the face that is in tension under the design moment (bottom in a midspan simple-beam region, top over a continuous support).", src: "libretexts-mom", also: ["ncees-ref"] },
    { id: "fe145", ages: 'both', topic: "structural", s: "A load path is:", c: ["A construction haul road, used to move earth on the site", "The route loads take from where they are applied down to the foundation", "A sewer alignment through the site or right-of-way", "A surveying traverse around the property or job"], f: "A clear load path takes gravity and lateral loads from floors and walls through beams, columns or shear walls, and into the foundation. A load path is the route loads take from where they are applied down to the foundation. Every element in the path must be designed for its share.", src: "libretexts-mom", also: ["ncees-ref"] },
    { id: "fe146", ages: 'both', topic: "structural", s: "A 10 m simply supported beam has E=\\(200\\,\\mathrm{GPa}\\) and I=\\(1.0\\times 10^{-4}\\,\\mathrm{m}^{4}\\), with a midspan load of \\(20\\,\\mathrm{kN}\\). What is the midspan deflection?", c: ["\\(5.21\\,\\mathrm{mm}\\)", "\\(20.8\\,\\mathrm{mm}\\)", "\\(10.4\\,\\mathrm{mm}\\)", "\\(41.7\\,\\mathrm{mm}\\)"], f: "\\(\\delta=PL^{3}/(48EI)=20000(10)^{3}/(48\\times 200\\times 10^{9}\\times 1.0\\times 10^{-4})=0.0208\\) m \\(=20.8\\) mm.", src: "libretexts-mom", also: ["ncees-ref"] },
    { id: "fe147", ages: 'both', topic: "geotech", s: "In the USCS, a soil labeled SW is:", c: ["A high-plasticity clay with low permeability", "Well-graded sand with little or no fines", "A peat or other highly organic soil", "A poorly graded clean sand with a narrow size range"], f: "Clays use C (CL, CH), peat is PT, and poorly graded sands are SP. USCS symbol SW means well-graded sand with little or no fines.", src: "nrcs-ssm", also: ["usace-settle", "ncees-ref"] },
    { id: "fe148", ages: 'both', topic: "geotech", s: "Void ratio e is defined as:", c: ["Volume of solids divided by volume of voids, inverted", "Volume of voids divided by volume of solids", "Weight of water divided by weight of solids", "Porosity plus 1"], f: "The quantity e is \\(V_v/V_s\\), the volume of voids divided by volume of solids.", src: "nrcs-ssm", also: ["usace-settle", "ncees-ref"], img: "img/fe-soil-phase.svg", imgAlt: "Soil phase diagram with volumes of air, water, and solids on the left and corresponding weights on the right.", imgAsk: true },
    { id: "fe149", ages: 'both', topic: "geotech", s: "A soil has void ratio 0.60. What is the porosity n?", c: ["0.600", "0.375", "1.60", "0.400"], f: "Porosity is \\(n=e/(1+e)=0.375\\) for the given void ratio.", src: "nrcs-ssm", also: ["usace-settle", "ncees-ref"], img: "img/fe-soil-phase.svg", imgAlt: "Soil phase diagram with volumes of air, water, and solids on the left and corresponding weights on the right." },
    { id: "fe150", ages: 'both', topic: "geotech", s: "A saturated soil has Gs=2.70 and e=0.60. Unit weight of water is \\(9.81\\,\\mathrm{kN}/\\mathrm{m}^{3}\\). What is the saturated unit weight?", c: ["\\(9.81\\,\\mathrm{kN}/\\mathrm{m}^{3}\\)", "\\(20.2\\,\\mathrm{kN}/\\mathrm{m}^{3}\\)", "\\(26.5\\,\\mathrm{kN}/\\mathrm{m}^{3}\\)", "\\(12.4\\,\\mathrm{kN}/\\mathrm{m}^{3}\\)"], f: "Saturated unit weight is \\(\\gamma_{sat}=(G_s+e)\\gamma_w/(1+e)=(2.70+0.60)9.81/1.60=20.23\\) kN/m\\(^{3}\\), about \\(20.2\\,\\mathrm{kN}\\)/m\\(^{3}\\). \\(G_s\\gamma_w=26.5\\) is the solids unit weight, not the bulk saturated value.", src: "nrcs-ssm", also: ["usace-settle", "ncees-ref"] },
    { id: "fe151", ages: 'both', topic: "geotech", s: "Effective stress is defined as:", c: ["Total stress plus pore-water pressure", "Total stress minus the pore-water pressure", "Pore pressure minus total stress", "Unit weight times porosity"], f: "Terzaghi's effective stress is \\(\\sigma'=\\sigma-u\\). Effective stress is total stress minus pore-water pressure. Strength and compressibility of soil are governed by effective stress, not total stress alone.", src: "nrcs-ssm", also: ["usace-settle", "ncees-ref"] },
    { id: "fe152", ages: 'both', topic: "geotech", s: "A 4.0 m layer of saturated clay has a unit weight of \\(18\\,\\mathrm{kN}/\\mathrm{m}^{3}\\). The water table is at the surface. What is the effective vertical stress at the bottom of the layer? Use \\(\\gamma_w=9.81\\,\\mathrm{kN}/\\mathrm{m}^{3}\\).", c: ["72.0 kPa", "32.8 kPa", "39.2 kPa", "18.0 kPa"], f: "Effective stress is 32.8 kPa after subtracting pore pressure from total stress at that depth.", src: "nrcs-ssm", also: ["usace-settle", "ncees-ref"] },
    { id: "fe153", ages: 'both', topic: "geotech", s: "The standard penetration test (SPT) N-value is:", c: ["The unconfined compressive strength in kPa, from a lab cylinder or vane", "Blows to drive \\(300\\,\\mathrm{mm}\\) after a seating interval", "The liquid limit of the fines, from a cup or cone test", "The coefficient of consolidation, from a time-settlement curve"], f: "SPT N is the number of blows of a standard hammer to drive the sampler \\(300\\,\\mathrm{mm}\\) (12 in) after a seating increment. It is a field index used in many empirical correlations.", src: "nrcs-ssm", also: ["usace-settle", "ncees-ref"] },
    { id: "fe154", ages: 'both', topic: "geotech", s: "At-rest lateral earth pressure is typically used for:", c: ["A wall that tilts out enough to reach the active condition", "A rigid wall that does not move enough to reach active or passive pressure", "A wall pushed into the soil enough to reach the passive condition", "A floating barge, unconnected to the soil"], f: "Active pressure needs outward movement, passive needs movement into the soil, and at-rest (\\(K_0\\)) applies when the wall does not move enough to mobilize either.", src: "nrcs-ssm", also: ["usace-settle", "ncees-ref"], img: "img/fe-retaining.svg", imgAlt: "A vertical retaining wall holding a soil backfill of height H." },
    { id: "fe155", ages: 'both', topic: "geotech", s: "For a loose sand with friction angle \\(30^{\\circ}\\) and no wall friction, Rankine active \\(K_a\\) is \\((1-\\sin\\phi)/(1+\\sin\\phi)\\), which equals:", c: ["3.00", "0.333", "0.500", "1.00"], f: "Active earth-pressure coefficient at a 30-degree friction angle is 0.333.", src: "nrcs-ssm", also: ["usace-settle", "ncees-ref"], img: "img/fe-retaining.svg", imgAlt: "A retaining wall with a level soil backfill of height H.", imgAsk: true },
    { id: "fe156", ages: 'both', topic: "geotech", s: "The resultant Rankine active force on a smooth vertical wall of height \\(H\\), with level backfill of unit weight \\(\\gamma\\), is:", c: ["\\(K_a\\gamma H^{2}/3\\)", "\\(0.5 K_a\\gamma H^{2}\\)", "\\(2 K_a\\gamma H^{2}\\)", "\\(K_a\\gamma H/2\\)"], f: "Active pressure at the base is \\(K_a\\gamma H\\), varying linearly from 0 at the surface, so the force is the area of that triangle: \\(\\frac{1}{2}K_a\\gamma H^{2}\\).", src: "nrcs-ssm", also: ["usace-settle", "ncees-ref"], img: "img/fe-retaining.svg", imgAlt: "A vertical retaining wall of height H with a level backfill.", imgAsk: true },
    { id: "fe157", ages: 'both', topic: "geotech", s: "A 6.0 m smooth vertical wall has a level sand backfill with \\(\\gamma=18\\,\\mathrm{kN}/\\mathrm{m}^{3}\\) and \\(K_a=1/3\\). What is the active force per meter of wall?", c: ["\\(216\\,\\mathrm{kN}\\)/m", "\\(108\\,\\mathrm{kN}\\)/m", "\\(36\\,\\mathrm{kN}\\)/m", "\\(54\\,\\mathrm{kN}\\)/m"], f: "\\(P_a=\\frac{1}{2}K_a\\gamma H^{2}=\\frac{1}{2}(1/3)(18)(36)=108\\,\\mathrm{kN}/\\mathrm{m}\\), or 108 kN/m of wall.", src: "nrcs-ssm", also: ["usace-settle", "ncees-ref"], img: "img/fe-retaining.svg", imgAlt: "A  retaining wall of height H with level backfill.", imgAsk: true },
    { id: "fe158", ages: 'both', topic: "geotech", s: "The drained shear strength of a sand (c'=0) is:", c: ["su, a constant independent of stress", "\\(\\sigma'\\tan\\phi'\\)", "\\(\\sigma\\tan 0\\), taking the friction angle as zero", "The liquid limit times area"], f: "The Mohr-Coulomb drained strength of a cohesionless soil is \\(\\tau=\\sigma'\\tan\\phi'\\). Undrained strength \\(s_u\\) is used for short-term clay problems.", src: "nrcs-ssm", also: ["usace-settle", "ncees-ref"] },
    { id: "fe159", ages: 'both', topic: "geotech", s: "Terzaghi's bearing capacity equation for a strip footing includes terms for:", c: ["The SPT N-value from a boring log, omitting cohesion or surcharge terms", "Cohesion, surcharge, and soil weight, each with a bearing factor", "Wind load on the superstructure, a lateral load and drift case", "The Manning roughness of the site, a flow and resistance term"], f: "The classic form is \\(q_c=c N_c + q N_q + 0.5\\gamma B N_\\gamma\\), with factors \\(N_c,N_q,N_\\gamma\\) that depend on \\(\\phi\\). The terms are cohesion, surcharge, and soil weight, each with a bearing factor. Shape, depth, and inclination factors are added in later extensions.", src: "nrcs-ssm", also: ["usace-settle", "ncees-ref"], img: "img/fe-footing.svg", imgAlt: "A square spread footing of width B under a column." },
    { id: "fe160", ages: 'both', topic: "geotech", s: "A 2.0 m square footing is founded at a shallow depth on sand. Increasing the width B, all else equal, generally:", c: ["Reduces settlement to zero in each case", "Increases the self-weight term of bearing capacity", "Leaves the \\(N_\\gamma\\) term unchanged", "Converts the footing into a deep foundation automatically"], f: "The \\(0.5\\gamma B N_\\gamma\\) term grows with width. Increasing footing width increases the self-weight term of bearing capacity. Settlement also tends to increase with load and width, so it still must be checked.", src: "nrcs-ssm", also: ["usace-settle", "ncees-ref"], img: "img/fe-footing.svg", imgAlt: "A spread footing of width B supporting a column.", imgAsk: true },
    { id: "fe161", ages: 'both', topic: "geotech", s: "Primary consolidation settlement of a clay layer is most closely tied to:", c: ["Instant elastic compression, before pore water is expelled", "Water leaving the voids as effective stress increases", "A sudden shear failure of the footing", "Heave from frost"], f: "Primary consolidation is time-dependent compression as pore pressure dissipates and effective stress rises. Primary consolidation is water leaving the voids as effective stress increases. Immediate settlement is a separate, often undrained, component.", src: "usace-settle", also: ["ncees-ref"] },
    { id: "fe162", ages: 'both', topic: "geotech", s: "A normally consolidated clay layer is 4.0 m thick, Cc=0.30, e0=0.90, and the effective stress will double. What is the primary consolidation settlement?", c: ["0.300 m", "0.190 m", "0.090 m", "0.600 m"], f: "Primary consolidation settlement is \\(s_c=C_c H/(1+e_0)\\log(\\sigma'_2/\\sigma'_1)=0.30(4.0)/1.90\\times\\log(2)=0.6316\\times 0.30103=0.190\\,\\mathrm{m}\\).", src: "usace-settle", also: ["ncees-ref"] },
    { id: "fe163", ages: 'both', topic: "geotech", s: "A common slope-stability concern in a newly placed fill is:", c: ["Heave from frost in the fill, before a shear surface forms", "A slip surface forming in weak soil or along a weak layer", "A guaranteed factor of safety of 10, skipped in analysis", "Settlement of a nearby spread footing or mat"], f: "Fills, cuts, and embankments can fail along a slip surface if shear strength is exceeded. A common slope failure is a slip surface forming in weak soil or along a weak layer. Methods such as slices or charts are used to estimate a factor of safety.", src: "usace-slope", also: ["usace-settle", "ncees-ref"] },
    { id: "fe164", ages: 'both', topic: "geotech", s: "Lime or cement added to a wet, fine-grained soil is typically intended to:", c: ["Increase the organic content and silt of the soil", "Improve the strength and workability by chemical stabilization", "Dissolve the sand-size particles and gravel", "Treat underdrains as optional, and drop further design"], f: "Chemical stabilization with lime or cement can improve strength and workability of fine-grained soils by reducing plasticity. It does not remove the need to consider drainage and mix design.", src: "nrcs-ssm", also: ["usace-settle", "ncees-ref"] },
    { id: "fe165", ages: 'both', topic: "geotech", s: "A deep foundation is chosen instead of a spread footing when:", c: ["Each site is required to use piles, including sites on shallow rock", "Shallow soil is too weak or compressible, or a strong layer is deep", "Spread footings cost less, so they should be used when the shallow soil is weak or the load is light", "Deep foundations eliminate the need to check settlement"], f: "Piles, drilled shafts, and other deep foundations transfer load to deeper, stronger layers when shallow soils are weak, compressible, or otherwise unsuitable.", src: "nrcs-ssm", also: ["usace-settle", "ncees-ref"], img: "img/fe-footing.svg", imgAlt: "A shallow spread footing under a column, used here for contrast with deep foundations." },
    { id: "fe166", ages: 'both', topic: "geotech", s: "The liquid limit of a soil is:", c: ["The specific gravity of the solids, a density ratio for the particles", "The water content at the plastic-to-liquid boundary, from the cup or cone test", "The coefficient of permeability, or a flow-rate property", "The SPT blow count, a field penetration resistance"], f: "Atterberg limits (LL, PL, and the plasticity index PI=LL-PL) classify fine-grained soils and correlate with their behavior. The liquid limit is the water content at the plastic-to-liquid boundary, from the cup or cone test. LL is a water content, not a stress or N-value.", src: "nrcs-ssm", also: ["usace-settle", "ncees-ref"] },
    { id: "fe167", ages: 'both', topic: "trans", s: "Stopping sight distance is mainly the sum of:", c: ["The length of a vertical curve", "Brake-reaction distance plus braking distance", "The number of lanes on the typical section", "The structural number for the surface"], f: "SSD is the distance traveled during perception-reaction plus the distance to brake to a stop. Design tables depend on speed, grade, and assumed deceleration.", src: "fhwa-geom", also: ["ncees-ref"] },
    { id: "fe168", ages: 'both', topic: "trans", s: "A car travels at \\(20\\,\\mathrm{m/s}\\). Reaction time is 2.5 s and braking deceleration is \\(3.4\\,\\mathrm{m}/\\mathrm{s}^{2}\\) on a level road. What is the stopping distance?", c: ["50.0 m", "108.8 m", "58.8 m", "80 m"], f: "Distance is \\(Vt+V^{2}/(2a)=20(2.5)+400/(6.8)=50+58.8=108.8\\) m. Leaving out either term is a common error.", src: "fhwa-geom", also: ["ncees-ref"] },
    { id: "fe169", ages: 'both', topic: "trans", s: "Superelevation on a horizontal curve is used to:", c: ["Remove the need for tire friction on the curve", "Help the vehicle change direction by tilting the roadway", "Replace the design radius with a sharp kink", "Increase the grade of a crest vertical curve"], f: "Superelevation e, with side friction f, relates to speed and radius by a design equation of the form \\(e+f=v^{2}/(gR)\\) (in consistent units). Superelevation is used to help the vehicle change direction by tilting the roadway. It does not replace friction entirely.", src: "fhwa-geom", also: ["ncees-ref"], img: "img/fe-curve.svg", imgAlt: "Horizontal circular curve: radius R from center O to PC, PI at the intersection of the two tangents, and PT on the forward tangent." },
    { id: "fe170", ages: 'both', topic: "trans", s: "A vehicle travels at \\(20\\,\\mathrm{m/s}\\) on a \\(200\\,\\mathrm{m}\\) radius curve. Using \\(e+f=V^{2}/(gR)\\) and \\(g=9.81\\,\\mathrm{m/s}^{2}\\), what is \\(e+f\\)?", c: ["0.100", "0.204", "0.500", "2.04"], f: "\\(e+f=V^{2}/(gR)=400/(9.81\\times 200)=0.204\\). This required side-force share is then split between superelevation and friction in design.", src: "fhwa-geom", also: ["ncees-ref"], img: "img/fe-curve.svg", imgAlt: "Horizontal circular curve: radius R from center O to PC, PI at the intersection of the two tangents, and PT on the forward tangent.", imgAsk: true },
    { id: "fe171", ages: 'both', topic: "trans", s: "The length of a circular curve with radius R and deflection (intersection) angle Delta in radians is:", c: ["\\(2\\pi R\\), for an arbitrary deflection angle", "\\(R\\Delta\\)", "\\(R/\\Delta\\)", "\\(\\Delta/R\\)"], f: "Arc length is \\(L=R\\Delta\\) when \\(\\Delta\\) is in radians (or \\(L=2\\pi R(\\Delta/360)\\) when \\(\\Delta\\) is in degrees).", src: "fhwa-geom", also: ["ncees-ref"], img: "img/fe-curve.svg", imgAlt: "Horizontal circular curve: radius R from center O to PC, PI at the intersection of the two tangents, and PT on the forward tangent.", imgAsk: true },
    { id: "fe172", ages: 'both', topic: "trans", s: "A circular curve has R=250 m and a deflection angle of 60 degrees. What is the curve length?", c: ["250 m", "262 m", "157 m", "471 m"], f: "\\(L=R\\Delta=250(60\\pi/180)=261.8\\) m, about 262 m. A full circle would be \\(2\\pi R=1,571\\) m; one sixth of that is this 60° arc.", src: "fhwa-geom", also: ["ncees-ref"], img: "img/fe-curve.svg", imgAlt: "Horizontal circular curve: radius R from center O to PC, PI at the intersection of the two tangents, and PT on the forward tangent.", imgAsk: true },
    { id: "fe173", ages: 'both', topic: "trans", s: "In a simple traffic stream, flow q, density k, and space-mean speed v are related by:", c: ["q = k / v", "q = k v", "q = k + v", "q = v / k"], f: "The fundamental relation is \\(q=kv\\) when units are consistent (for example veh/h = veh/km times km/h).", src: "fhwa-geom", also: ["ncees-ref"] },
    { id: "fe174", ages: 'both', topic: "trans", s: "Density is 20 veh/km and space-mean speed is 50 km/h. What is the flow?", c: ["1,000 km/h", "1,000 veh/h", "40 veh/h", "25 veh/h"], f: "Traffic flow is density times speed: \\(q=kv=20(50)=1,000\\) veh/h.", src: "fhwa-geom", also: ["ncees-ref"] },
    { id: "fe175", ages: 'both', topic: "trans", s: "A STOP sign is an example of which kind of traffic control device?", c: ["A guide sign by itself", "A regulatory sign", "A lane marking, excluding a sign", "A roadway lighting fixture"], f: "A regulatory sign (stop, yield, speed limit) tells drivers what they must do. Guide signs give navigation information. The MUTCD groups devices by function and sets their use.", src: "fhwa-mutcd", also: ["ncees-ref"] },
    { id: "fe176", ages: 'both', topic: "trans", s: "A yellow center line that is dashed on your side generally means:", c: ["The road is one-way, so opposing traffic is absent", "Passing is allowed on your side when the way is clear and legal", "A railroad crossing and a school zone are just ahead on the route", "You have to stop at each dashed line on the lane"], f: "On a two-way roadway, a dashed yellow line on your side indicates that passing is allowed on your side when the way is clear and legal. A solid yellow on your side means do not pass.", src: "fhwa-mutcd", also: ["ncees-ref"] },
    { id: "fe177", ages: 'both', topic: "trans", s: "Trip generation in transportation planning estimates:", c: ["How many lanes a mid-block freeway segment needs", "How many trips a land use will produce or attract", "What fare or headway a transit agency should set", "How thick a surface course of asphalt should be"], f: "Trip generation relates land use (homes, shops, offices) to the number of trips produced or attracted. Later steps include distribution, mode choice, and assignment.", src: "fhwa-geom", also: ["ncees-ref"] },
    { id: "fe178", ages: 'both', topic: "trans", s: "Flexible pavement design is concerned mainly with:", c: ["The design of a steel truss chord for a bridge superstructure", "Layer thicknesses and materials over the prepared subgrade", "The BOD of stormwater in a ditch and a swale", "The paint and thermoplastic used for lane markings on the surface"], f: "Flexible (asphalt) pavements are layered systems. A flexible pavement is designed as layer thicknesses and materials over a prepared subgrade. Thickness and material quality are chosen for traffic, subgrade support, and climate, with drainage being critical.", src: "fhwa-geom", also: ["ncees-ref"] },
    { id: "fe179", ages: 'both', topic: "trans", s: "A common reason to rehabilitate a pavement is:", c: ["The pavement is new and is free of distress or cracking", "Damage or a poor surface that hurts safety and service", "A plan to add lanes or ramps, and to drop geometric design", "A way to skip drainage and crown on the typical section"], f: "Rehabilitation (overlay, recycling, reconstruction) is used when distress, roughness, or structural capacity is no longer acceptable. Rehabilitation is used for damage or a poor surface that hurts safety and service. Drainage and a proper design still matter.", src: "fhwa-geom", also: ["ncees-ref"] },
    { id: "fe180", ages: 'both', topic: "trans", s: "Freeway capacity analysis in the HCM tradition is based mainly on:", c: ["Sign legend colors, independent of traffic-flow data", "Speed, flow, and density, with a defined level of service", "The age of the pavement surface course, and a friction term", "The Manning n of the travel lanes, and a roughness term"], f: "Highway Capacity Manual methods use flow, speed, density, and heavy-vehicle and geometry adjustments to assign a level of service. They are not a pavement-condition test.", src: "fhwa-geom", also: ["ncees-ref"] },
    { id: "fe181", ages: 'both', topic: "trans", s: "A vertical crest curve is provided mainly to:", c: ["Drop the horizontal curves from the route alignment", "Provide the sight distance and a smooth change of grade", "Increase the superelevation of a flat tangent and curve", "Eliminate drainage and ditches on the crest"], f: "Crest vertical curves are designed to provide sight distance over the hill and a smooth change of grade. Sag curves have different (often headlight or comfort) controls.", src: "fhwa-geom", also: ["ncees-ref"] },
    { id: "fe182", ages: 'both', topic: "trans", s: "Intersection sight distance is needed so that a driver can:", c: ["Read a map and keep your eyes off the road", "See conflicting traffic in time to stop or enter safely", "Ignore the traffic control devices at the intersection", "Travel at an arbitrary speed when a gap is unavailable"], f: "Intersection sight distance lets a driver see conflicting traffic in time to stop or enter safely. At intersections, drivers need enough sight distance along the approaches and into the intersection to detect conflicts and act. Landscaping and parked cars often block this sight triangle.", src: "fhwa-geom", also: ["ncees-ref"] },
    { id: "fe183", ages: 'both', topic: "trans", s: "A two-lane highway has a 12 ft lane and a 6 ft shoulder. The paved width of one direction of travel (lane plus shoulder) is:", c: ["12 ft", "18 ft", "6 ft", "24 ft"], f: "Lane plus shoulder is \\(12+6=18\\) ft on that side. The opposite direction is counted separately.", src: "fhwa-geom", also: ["ncees-ref"] },
    { id: "fe184", ages: 'both', topic: "trans", s: "Transportation safety studies often use crash rates because:", c: ["They treat each crash the same, regardless of traffic volume", "They account for exposure, not only raw crash counts", "They make geometric design no longer necessary", "They measure only the pigment in pavement markings"], f: "A crash rate divides crashes by exposure (vehicle-miles, entering vehicles, or similar), so studies account for exposure, not only raw crash counts. A high-volume site can have more crashes but a lower rate than a low-volume site.", src: "fhwa-geom", also: ["ncees-ref"] },
    { id: "fe185", ages: 'both', topic: "construction", s: "In a design-bid-build project, the usual first procurement step after design is complete is:", c: ["Start construction before the design or bid documents are issued", "Advertise and bid the work, then award it to a contractor", "Award the work first, then finish the design and estimates with the same firm", "Ask the resident inspector to pick a contractor and a crew from the site"], f: "Design-bid-build completes the design, then bids the construction. In design-bid-build, the owner will advertise and bid the work, then award it to a contractor. Design-build is a different delivery method in which one entity provides both design and construction.", src: "fhwa-contracts", also: ["ncees-spec"] },
    { id: "fe186", ages: 'both', topic: "construction", s: "A lump-sum contract generally means the contractor is paid:", c: ["A cost-plus fee that leaves the agreement total unstated", "A stated total price for the defined scope", "Payment by the hour that leaves the scope of work undefined", "A handshake and a start date"], f: "A lump-sum (stipulated-sum) price covers the defined scope for a stated total. Unit-price and cost-plus contracts handle quantity risk and reimbursement differently.", src: "fhwa-contracts", also: ["ncees-spec"] },
    { id: "fe187", ages: 'both', topic: "construction", s: "OSHA construction rules are intended mainly to:", c: ["Establish the architectural style of the finished building", "Protect workers from recognized job-site hazards", "Issue PE licenses to the design engineers", "Replace the building codes with a single wage table"], f: "OSHA sets and enforces workplace safety standards, including construction (for example fall protection, trenches, and equipment). OSHA's construction rules are meant to protect workers from recognized job-site hazards. Building design codes and PE licensure are separate.", src: "osha-const", also: ["ncees-spec"] },
    { id: "fe188", ages: 'both', topic: "construction", s: "A trench 6 ft deep in soil, used as a workplace, generally requires:", c: ["No protective system, treating a 6 ft trench as a shallow excavation", "A protective system, unless a stated exception in the standard applies", "A warning sign, and neither sloping, shoring, nor a shield", "A walkway laid on the spoil pile beside the trench"], f: "OSHA's excavation standard requires a protective system for most trenches 5 ft or deeper (and for shallower trenches if there is a hazard), unless a stated exception in the standard applies. A competent person must inspect the excavation.", src: "osha-const", also: ["ncees-spec"] },
    { id: "fe189", ages: 'both', topic: "construction", s: "In a CPM network, a critical activity is one that:", c: ["Can slip and still keep the project finish date unchanged", "Has zero total float and lies on the critical path", "Affects the cost account and budget and leaves the scheduled finish unchanged", "Has the longest duration, whether or not remaining float and lag are large"], f: "Total float is the time an activity can slip without delaying the project as scheduled. Critical activities have zero, or minimum, total float and form a critical path.", src: "fhwa-schedule", also: ["ncees-spec"] },
    { id: "fe190", ages: 'both', topic: "construction", s: "Activity A takes 5 days. B (8 days) and C (3 days) both follow A and can run in parallel. D (2 days) follows both B and C. What is the project duration?", c: ["10 days", "15 days", "18 days", "8 days"], f: "The path A-B-D is 15 days. The project duration is the longest path, 15 days, and A, B, and D are critical.", src: "fhwa-schedule", also: ["ncees-spec"] },
    { id: "fe191", ages: 'both', topic: "construction", s: "Earned value: PV=100, EV=80, AC=90. What is the cost variance CV=EV-AC?", c: ["10", "-10", "-20", "80"], f: "Cost variance is \\(CV=EV-AC=-10\\), a cost overrun.", src: "fhwa-contracts", also: ["ncees-spec"] },
    { id: "fe192", ages: 'both', topic: "construction", s: "Using the same values PV=100, EV=80, AC=90, the schedule variance SV=EV-PV is:", c: ["-10", "-20", "20", "10"], f: "Schedule variance is \\(SV=EV-PV=80-100=-20\\). Negative SV means less work has been earned than planned.", src: "fhwa-contracts", also: ["ncees-spec"] },
    { id: "fe193", ages: 'both', topic: "construction", s: "A quantity takeoff is used in estimating to:", c: ["Rewrite the specifications in full after the work is already in place", "Measure and list the work quantities from the documents", "Set OSHA policy and citations for the nation", "Design the structural members and connections in place of the engineer"], f: "A takeoff is used to measure and list the work quantities from the documents (earthwork, concrete, steel, and so on) that are then priced. It is not a structural design step.", src: "fhwa-contracts", also: ["ncees-spec"] },
    { id: "fe194", ages: 'both', topic: "construction", s: "A concrete wall is 20 m long, 3.0 m high, and 0.30 m thick. What is the concrete volume?", c: ["\\(60\\,\\mathrm{m}^{3}\\)", "\\(18\\,\\mathrm{m}^{3}\\)", "\\(6.0\\,\\mathrm{m}^{3}\\)", "\\(23.3\\,\\mathrm{m}^{3}\\)"], f: "Volume is \\(L\\times H\\times t=20(3.0)(0.30)=18\\) m\\(^{3}\\). Forgetting the thickness or using area alone are common takeoff errors.", src: "fhwa-contracts", also: ["ncees-spec"] },
    { id: "fe195", ages: 'both', topic: "construction", s: "Equipment production for a hauling operation depends mainly on:", c: ["The paint color of the machine body", "Cycle time, load size, and operating efficiency", "The brand of the tires and rims", "The bid date and time in the procurement documents"], f: "Production often depends on cycle time, load size, and operating efficiency (load per cycle times cycles per hour times efficiency). Cycle time includes load, haul, dump, and return.", src: "fhwa-schedule", also: ["ncees-spec"] },
    { id: "fe196", ages: 'both', topic: "construction", s: "A loader moves \\(12\\,\\mathrm{m}^{3}\\) per cycle. A cycle takes 15 minutes. Efficiency is a 50-minute hour. What is production?", c: ["\\(48\\,\\mathrm{m}^{3}/\\mathrm{h}\\)", "\\(40\\,\\mathrm{m}^{3}/\\mathrm{h}\\)", "\\(12\\,\\mathrm{m}^{3}/\\mathrm{h}\\)", "\\(8\\,\\mathrm{m}^{3}/\\mathrm{h}\\)"], f: "A 50-minute hour at this cycle production gives \\(40\\,\\mathrm{m}^{3}/\\mathrm{h}\\).", src: "fhwa-schedule", also: ["ncees-spec"] },
    { id: "fe197", ages: 'both', topic: "construction", s: "Temporary erosion control on a construction site is used to:", c: ["Add fertilizer to the finished landscape", "Limit sediment leaving the site during construction", "Increase the peak storm discharge from unprotected bare soil", "Replace the site's permanent drainage structures"], f: "Silt fences, inlet protection, tracking pads, and similar measures limit sediment leaving the site during construction. They are often required by permits and must be maintained.", src: "epa-waste", also: ["ncees-spec"] },
    { id: "fe198", ages: 'both', topic: "construction", s: "On a set of engineering drawings, a section cut identified on the plan is used to:", c: ["Show a plan or aerial view of the work from above", "Show a vertical slice of hidden or typical work", "List the bid prices in the proposal form", "Record daily time cards in the field office"], f: "Section views show the project as if it were cut, so thicknesses, elevations, and hidden parts can be read. A section cut is used to show a vertical slice of hidden or typical work. The cut line and view arrows on the plan point to that section.", src: "fhwa-contracts", also: ["ncees-spec"] },
    { id: "fe199", ages: 'both', topic: "construction", s: "A finish elevation is 12.40 m and the existing ground is 11.10 m. What is the fill height?", c: ["12.40 m", "1.30 m", "11.10 m", "23.50 m"], f: "Fill is the difference: \\(12.40-11.10=1.30\\) m. Adding the elevations has no meaning here.", src: "fhwa-contracts", also: ["ncees-spec"] },
    { id: "fe200", ages: 'both', topic: "construction", s: "Shop drawings, once reviewed, are used mainly to:", c: ["Change the agreement into a verbal understanding only", "Show how the contractor or fabricator will meet the design documents", "Take the place of required job-site safety inspections", "Set the owner's tax rate for the completed work"], f: "Shop drawings give fabrication and installation detail consistent with the contract documents. Shop drawings show how the contractor or fabricator will meet the design documents. Review does not automatically shift design responsibility unless the contract says so; the design documents still govern.", src: "fhwa-contracts", also: ["ncees-spec"] },
  ]
});
